window.BIOMASTER = window.BIOMASTER || {};
window.BIOMASTER.MCQ_CELLULAR = [{"id":"MCQ-CL-001","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân bào","q":"Một tế bào sinh dưỡng của người ($2n = 46$) đang ở kỳ sau của quá trình nguyên phân. Số nhiễm sắc thể đơn và số tâm động trong tế bào lúc này lần lượt là:","opts":["$46$ NST đơn và $46$ tâm động.","$92$ NST kép và $46$ tâm động.","$46$ NST kép và $92$ tâm động.","$92$ NST đơn và $92$ tâm động."],"ans":3,"exp":"Ở kỳ sau nguyên phân, NST kép tách thành 2 NST đơn phân ly về 2 cực $\\Rightarrow 4n = 92$ NST đơn và $92$ tâm động."},{"id":"MCQ-CL-002","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến NST","q":"Một loài thực vật có $2n = 24$. Số lượng nhiễm sắc thể trong một tế bào sinh dưỡng của thể ba kép ($2n+1+1$) và số dạng thể ba kép tối đa của loài lần lượt là:","opts":["$26$ NST và $12$ dạng.","$36$ NST và $66$ dạng.","$25$ NST và $12$ dạng.","$26$ NST và $66$ dạng."],"ans":3,"exp":"$2n+1+1 = 26$ NST. Có $n = 12$ cặp NST nên số dạng thể ba kép $= C^2_{12} = 66$ dạng."},{"id":"MCQ-CL-003","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nguyên phân","q":"Có 5 tế bào sinh dưỡng của một loài ($2n = 20$) nguyên phân liên tiếp 3 lần. Tổng số tế bào con tạo thành và số nhiễm sắc thể môi trường nội bào đã cung cấp cho quá trình trên lần lượt là:","opts":["$80$ tế bào và $700$ NST.","$40$ tế bào và $800$ NST.","$40$ tế bào và $700$ NST.","$15$ tế bào và $700$ NST."],"ans":2,"exp":"Số tế bào con $= 5 \\times 2^3 = 40$. Số NST môi trường cung cấp $= 5 \\times 20 \\times (2^3 - 1) = 700$ NST."},{"id":"MCQ-CL-004","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Ở một loài động vật ($2n = 16$), có 20 tế bào sinh trứng tiến hành giảm phân bình thường. Số trứng được tạo ra và số thể cực (thể định hướng) bị tiêu biến lần lượt là:","opts":["$20$ trứng và $20$ thể cực.","$20$ trứng và $60$ thể cực.","$80$ trứng và $0$ thể cực.","$60$ trứng và $20$ thể cực."],"ans":1,"exp":"Mỗi tế bào sinh trứng giảm phân tạo 1 trứng và 3 thể cực $\\Rightarrow 20$ tế bào tạo $20$ trứng và $60$ thể cực."},{"id":"MCQ-CL-005","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến cấu trúc NST","q":"Dạng đột biến cấu trúc nhiễm sắc thể nào sau đây được ứng dụng để loại bỏ các gen không mong muốn hoặc xác định vị trí của gen trên nhiễm sắc thể (lập bản đồ mất đoạn), nhưng thường gây giảm sức sống cho thể đột biến?","opts":["Chuyển đoạn trên cùng một NST.","Mất đoạn NST.","Đảo đoạn NST.","Lặp đoạn NST."],"ans":1,"exp":"Đột biến mất đoạn làm mất vật chất di truyền nên thường gây chết hoặc giảm sức sống, được dùng để định vị gen thông qua hiện tượng giả trội."},{"id":"MCQ-CL-006","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hội chứng ở người","q":"Hội chứng nào ở người có bộ nhiễm sắc thể thuộc dạng thể một ($2n - 1 = 45$) ở cặp nhiễm sắc thể giới tính ($XO$)?","opts":["Hội chứng Turner ($XO$).","Hội chứng Klinefelter ($XXY$).","Hội chứng siêu nữ ($XXX$).","Hội chứng Down ($3$ NST số 21)."],"ans":0,"exp":"Hội chứng Turner có bộ NST $44A + XO$ ($2n - 1 = 45$)."},{"id":"MCQ-CL-007","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc siêu hiển vi NST","q":"Đơn vị cấu trúc cơ bản của nhiễm sắc thể ở sinh vật nhân thực gồm một đoạn DNA dài khoảng $146$ cặp nucleotide quấn $1\\frac{3}{4}$ vòng quanh khối cầu gồm $8$ phân tử protein Histone được gọi là:","opts":["Sợi nhiễm sắc ($30\\text{ nm}$).","Sợi cơ bản ($10\\text{ nm}$).","Nucleosome.","Chromatid ($700\\text{ nm}$)."],"ans":2,"exp":"Nucleosome là đơn vị cấu trúc cơ bản của NST nhân thực (lõi 8 phân tử Histone + 146 cặp nu quấn quanh)."},{"id":"MCQ-CL-008","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giao tử TĐC","q":"Một loài có bộ NST $2n = 14$, mỗi cặp NST tương đồng đều dị hợp nhiều cặp gen. Trong giảm phân, có 2 cặp NST xảy ra TĐC tại 1 điểm và 1 cặp NST xảy ra TĐC tại 2 điểm không cùng lúc. Số loại giao tử tối đa tạo ra là:","opts":["$3072$ loại.","$2048$ loại.","$768$ loại.","$1536$ loại."],"ans":3,"exp":"$n = 7$. Số loại giao tử $= 2^{7+2} \\times 3^1 = 512 \\times 3 = 1536$ loại."},{"id":"MCQ-CL-009","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tế bào sinh tinh","q":"Có 4 tế bào sinh tinh của cơ thể có kiểu gen $AaBb\\frac{DE}{de}$ giảm phân bình thường, trong đó có 2 tế bào xảy ra trao đổi chéo giữa $D$ và $E$, còn 2 tế bào không có TĐC. Số loại tinh trùng tối đa tạo ra từ 4 tế bào này là:","opts":["$8$ loại.","$16$ loại.","$14$ loại.","$12$ loại."],"ans":3,"exp":"2 tế bào có TĐC cho tối đa $2 \\times 4 = 8$ loại; 2 tế bào không TĐC cho tối đa $2 \\times 2 = 4$ loại $\\Rightarrow$ Tổng tối đa $= 8 + 4 = 12$ loại."},{"id":"MCQ-CL-010","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Song nhị bội","q":"Lai loài cải củ ($2n_A = 18$) với loài cải bắp ($2n_B = 18$) thu được con lai xa $F_1$ bất thụ. Đa bội hóa $F_1$ bằng Colchicine thu được thể song nhị bội hữu thụ. Một tế bào sinh dưỡng của thể song nhị bội này đang ở kỳ sau của nguyên phân có bao nhiêu nhiễm sắc thể đơn?","opts":["$72$ NST đơn.","$36$ NST đơn.","$54$ NST đơn.","$18$ NST đơn."],"ans":0,"exp":"Thể song nhị bội có $2n_A + 2n_B = 36$ NST. Ở kỳ sau nguyên phân, số NST đơn tăng gấp đôi $= 36 \\times 2 = 72$ NST đơn."},{"id":"MCQ-CL-011","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Lệch bội 2n+1","q":"Ở cà độc dược, alen $A$ (hoa đỏ) trội hoàn toàn so với $a$ (hoa trắng). Cho cây thể ba $AAa$ tự thụ phấn. Biết cây thể ba giảm phân tạo giao tử $n$ và $n+1$ bình thường, nhưng hạt phấn $n+1$ không có khả năng thụ tinh (noãn $n+1$ thụ tinh bình thường). Tỉ lệ kiểu hình ở đời con $F_1$ là:","opts":["$17$ đỏ : $1$ trắng.","$11$ đỏ : $1$ trắng.","$8$ đỏ : $1$ trắng.","$35$ đỏ : $1$ trắng."],"ans":0,"exp":"Noãn của $AAa$ có lặn $a = \\frac{1}{6}$. Hạt phấn của $AAa$ chỉ có giao tử đơn bội $(\\frac{2}{3}A : \\frac{1}{3}a)$ thụ tinh được $\\Rightarrow aa = \\frac{1}{6} \\times \\frac{1}{3} = \\frac{1}{18} \\Rightarrow 17$ đỏ : $1$ trắng."},{"id":"MCQ-CL-012","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Nuôi cấy hạt phấn","q":"Một cơ thể thực vật có kiểu gen $AaBbddEe$ (các gen PLĐL). Lấy toàn bộ các loại hạt phấn của cây này nuôi cấy trong ống nghiệm tạo mô đơn bội, sau đó gây lưỡng bội hóa toàn bộ bằng Colchicine. Có tối đa bao nhiêu dòng thuần chủng khác nhau được tạo ra?","opts":["$81$ dòng.","$16$ dòng.","$8$ dòng.","$4$ dòng."],"ans":2,"exp":"Cơ thể $AaBbddEe$ dị hợp 3 cặp gen tạo $2^3 = 8$ loại hạt phấn $\\Rightarrow$ Lưỡng bội hóa tạo tối đa $8$ dòng thuần chủng."},{"id":"MCQ-CL-013","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hàm lượng DNA","q":"Hàm lượng DNA nhân trong một tế bào sinh tinh của một loài động vật ở pha $G_1$ là $6\\text{ pg}$. Hàm lượng DNA nhân của một tế bào ở kỳ giữa Giảm phân I, kỳ giữa Giảm phân II và trong một tinh trùng của loài này lần lượt là:","opts":["$12\\text{ pg}$ ; $6\\text{ pg}$ ; $3\\text{ pg}$.","$12\\text{ pg}$ ; $12\\text{ pg}$ ; $6\\text{ pg}$.","$6\\text{ pg}$ ; $6\\text{ pg}$ ; $3\\text{ pg}$.","$6\\text{ pg}$ ; $3\\text{ pg}$ ; $1.5\\text{ pg}$."],"ans":0,"exp":"Pha $G_1$ ($6\\text{ pg}$) $\\rightarrow$ Kỳ giữa GP I ($12\\text{ pg}$) $\\rightarrow$ Kỳ giữa GP II ($6\\text{ pg}$) $\\rightarrow$ Tinh trùng ($3\\text{ pg}$)."},{"id":"MCQ-CL-014","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Lặp đoạn Bar ở ruồi giấm","q":"Ở ruồi giấm, đột biến lặp đoạn 16A trên NST giới tính X làm mắt lồi bình thường trở thành mắt dẹt (Bar). Nếu đoạn 16A lặp lại 3 lần trên một NST X (do trao đổi chéo không cân), mắt ruồi càng dẹt hơn nữa. Hiện tượng biểu hiện kiểu hình phụ thuộc vào vị trí sắp xếp của các đoạn lặp trên NST này minh họa cho:","opts":["Di truyền tế bào chất.","Đột biến đa bội lẻ.","Hiệu quả vị trí (Position effect) của đột biến cấu trúc NST.","Đột biến lệch bội."],"ans":2,"exp":"Số lượng và vị trí sắp xếp các đoạn lặp 16A trên cùng 1 NST X hay chia đều trên 2 NST X làm thay đổi mức độ biểu hiện mắt dẹt — gọi là hiệu quả vị trí (Position effect)."},{"id":"MCQ-CL-015","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đa bội $4n$","q":"Thực hiện phép lai giữa hai cây tứ bội $P: AAaa \\times Aaaa$. Biết cây tứ bội giảm phân chỉ tạo giao tử $2n$ hữu thụ và $A$ trội hoàn toàn so với $a$. Tỉ lệ kiểu hình ở đời con $F_1$ là:","opts":["$35$ trội : $1$ lặn.","$3$ trội : $1$ lặn.","$5$ trội : $1$ lặn.","$11$ trội : $1$ lặn."],"ans":3,"exp":"$AAaa$ cho $\\frac{1}{6}aa$; $Aaaa$ cho $\\frac{1}{2}aa \\Rightarrow aaaa = \\frac{1}{12} \\Rightarrow 11$ trội : $1$ lặn."},{"id":"MCQ-CL-016","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Rối loạn phân bào - Đề HSG Tỉnh","q":"Cho phép lai $P$: ♂ $Aa \\times$ ♀ $Aa$. Trong giảm phân ở cơ thể bố, có $10\\%$ số tế bào sinh tinh không phân ly cặp $Aa$ ở Giảm phân II, cơ thể mẹ giảm phân bình thường. Tỉ lệ hợp tử lệch bội có kiểu gen $aaa$ ở đời con là:","opts":["$0.625\\%$.","$5\\%$.","$1.25\\%$.","$2.5\\%$."],"ans":2,"exp":"$10\\%$ tế bào sinh tinh rối loạn GP II tạo ra $2.5\\%$ tinh trùng $aa$. Kết hợp với trứng $a = 50\\%$ của mẹ $\\Rightarrow aaa = 2.5\\% \\times 0.5 = 1.25\\%$."},{"id":"MCQ-CL-017","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đảo đoạn ngoài tâm động - Đề HSG Tỉnh","q":"Ở một cá thể dị hợp tử về đột biến đảo đoạn ngoài tâm động (Paracentric inversion), nếu xảy ra trao đổi chéo đơn bên trong vòng đảo đoạn ở kỳ đầu Giảm phân I thì sản phẩm tạo thành ở kỳ sau Giảm phân I sẽ như thế nào?","opts":["Các nhiễm sắc thể không thể tiếp hợp ở kỳ đầu I.","Tạo ra 4 nhiễm sắc tử hoàn toàn bình thường.","Tạo ra các nhiễm sắc tử đều có 1 tâm động nhưng mang đột biến chuyển đoạn.","Tạo ra 1 nhiễm sắc tử có 2 tâm động (tạo cầu nhiễm sắc bị đứt gãy) và 1 nhiễm sắc tử không có tâm động (bị tiêu biến), làm các giao tử tái tổ hợp bị chết."],"ans":3,"exp":"Trao đổi chéo trong vòng đảo đoạn ngoài tâm động tạo ra 1 chromatid có 2 tâm động (dicentric bridge) và 1 mảnh không tâm động (acentric fragment), dẫn đến các giao tử tái tổ hợp bị chết."},{"id":"MCQ-CL-018","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chuyển đoạn tương hỗ - Đề HSG Tỉnh","q":"Một cá thể dị hợp tử về chuyển đoạn tương hỗ giữa NST số 1 và NST số 2. Trong Giảm phân I, 4 NST (1 bình thường, $1^\\prime$ chuyển đoạn, 2 bình thường, $2^\\prime$ chuyển đoạn) tiếp hợp tạo cấu trúc hình chữ thập. Kiểu phân ly nào giúp tạo ra các giao tử cân bằng di truyền (hữu thụ)?","opts":["Không có kiểu phân ly nào tạo giao tử hữu thụ.","Phân ly liền kề kiểu 2 (Adjacent-2).","Phân ly xen kẽ (Alternate segregation: NST 1 và 2 cùng về 1 cực; NST $1^\\prime$ và $2^\\prime$ cùng về cực kia).","Phân ly liền kề kiểu 1 (Adjacent-1)."],"ans":2,"exp":"Chỉ có kiểu phân ly xen kẽ (Alternate: 2 NST bình thường $1+2$ về một cực, 2 NST chuyển đoạn $1^\\prime+2^\\prime$ về cực kia) mới giữ đủ toàn bộ vật chất di truyền trong giao tử."},{"id":"MCQ-CL-019","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chu kỳ tế bào & Ung thư - Đề HSG Tỉnh","q":"Khi so sánh bản chất di truyền giữa Gen tiền ung thư (Proto-oncogene, ví dụ <i>Ras</i>) và Gen ức chế khối u (Tumor suppressor gene, ví dụ <i>p53</i> hoặc <i>Rb</i>), nhận định nào sau đây là chính xác?","opts":["Đột biến ở <i>p53</i> là đột biến trội hoàn toàn ở cấp độ tế bào.","Protein $Rb$ kích thích tế bào vượt qua điểm kiểm soát $G_1/S$.","Đột biến chuyển Proto-oncogene thành Oncogene là đột biến tăng chức năng (trội, chỉ cần 1 alen đột biến); còn đột biến ở Gen ức chế khối u là đột biến mất chức năng (lặn ở cấp tế bào, cần hỏng cả 2 alen).","Cả hai đều gây ung thư khi bị đột biến mất chức năng ở cả 2 alen."],"ans":2,"exp":"Oncogene là đột biến trội tăng chức năng (chỉ cần 1 alen); Gen ức chế khối u ($p53, Rb$) cần hỏng cả 2 alen mới mất kiểm soát chu kỳ tế bào."},{"id":"MCQ-CL-020","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chuyển đoạn Robertson - Đề HSG Tỉnh","q":"Hội chứng Down gia đình xảy ra do bố hoặc mẹ bình thường nhưng mang đột biến chuyển đoạn Robertson dung hợp tâm giữa NST số 14 và NST số 21 ($2n = 45$). Sau khi trừ đi các hợp tử chết ở giai đoạn phôi (thể một hoặc thể ba NST 14, thể một NST 21), tỉ lệ sinh con mắc hội chứng Down trong số các con sinh ra sống sót của cặp vợ chồng này là:","opts":["$\\frac{1}{3}$.","$\\frac{1}{2}$.","$\\frac{1}{6}$.","$\\frac{1}{4}$."],"ans":0,"exp":"Trong 6 tổ hợp hợp tử tạo thành có 3 tổ hợp chết phôi, còn lại 3 tổ hợp sống sót gồm: 1 bình thường, 1 mang chuyển đoạn cân bằng, và 1 mắc hội chứng Down chuyển đoạn $\\Rightarrow$ Tỉ lệ lý thuyết là $\\frac{1}{3}$."},{"id":"MCQ-CL-021","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Mất đoạn - Đề HSG Tỉnh","q":"Ở ruồi giấm, 4 gen lặn $(a, b, c, d)$ nằm trên cùng 1 NST. Đem lai dòng đồng hợp lặn $(abcd/abcd)$ với 3 dòng mang đột biến mất đoạn (Dòng 1, Dòng 2, Dòng 3) có các alen kiểu dại tương ứng ở NST không mất đoạn. Kết quả kiểu hình đời con thu được:<br>• Lai với Dòng 1: Biểu hiện kiểu hình lặn $a$ và $c$.<br>• Lai với Dòng 2: Biểu hiện kiểu hình lặn $c$ và $d$.<br>• Lai với Dòng 3: Biểu hiện kiểu hình lặn $b$ và $d$.<br>Trật tự đúng của 4 gen trên nhiễm sắc thể là:","opts":["$a - b - c - d$.","$b - a - c - d$.","$a - d - c - b$.","$a - c - d - b$."],"ans":3,"exp":"Biểu hiện giả trội cho biết các gen nằm trong cùng một đoạn mất liên tục: Dòng 1 mất $(a, c)$; Dòng 2 mất $(c, d) \\Rightarrow c$ nằm giữa $a$ và $d$ ($a - c - d$); Dòng 3 mất $(d, b) \\Rightarrow d$ nằm cạnh $b$. Vậy trật tự đúng là $a - c - d - b$."},{"id":"MCQ-CL-022","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Số lượng Thể Barr - Đề HSG Tỉnh","q":"Theo quy tắc bất hoạt nhiễm sắc thể X của Mary Lyon, số lượng thể Barr trong một tế bào sinh dưỡng của người có công thức $N_{\\text{Barr}} = \\text{Số NST X} - 1$. Vậy số lượng thể Barr trong tế bào sinh dưỡng của người mắc hội chứng Turner ($XO$), Klinefelter ($XXY$) và Siêu nữ ($XXX$) lần lượt là:","opts":["$0$ ; $0$ ; $1$.","$1$ ; $2$ ; $3$.","$1$ ; $1$ ; $2$.","$0$ ; $1$ ; $2$."],"ans":3,"exp":"Áp dụng công thức $\\text{Số NST X} - 1$: Turner ($XO$, có 1 X) $= 0$ thể Barr; Klinefelter ($XXY$, có 2 X) $= 1$ thể Barr; Siêu nữ ($XXX$, có 3 X) $= 2$ thể Barr."},{"id":"MCQ-CL-023","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc NST","q":"Vùng cấu trúc nào trên nhiễm sắc thể đóng vai trò là vị trí gắn với dây tơ vô sắc của thoi phân bào, giúp nhiễm sắc thể di chuyển chính xác về hai cực tế bào khi phân bào?","opts":["Trình tự khởi đầu nhân đôi (Ori).","Đầu mút (Telomere).","Tâm động (Centromere).","Vùng dị nhiễm sắc đầu NST."],"ans":2,"exp":"Tâm động chứa phức hợp protein thể động (kinetochore) là điểm bám của vi ống thoi phân bào kéo nhiễm sắc thể phân ly về 2 cực."},{"id":"MCQ-CL-024","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc NST","q":"Trong các mức độ cấu trúc siêu hiển vi của nhiễm sắc thể ở sinh vật nhân thực, sợi cơ bản có đường kính $11\\text{ nm}$ (chuỗi các Nucleosome) xoắn lại tạo thành cấu trúc bậc tiếp theo gọi là sợi nhiễm sắc có đường kính bao nhiêu?","opts":["$700\\text{ nm}$.","$2\\text{ nm}$.","$30\\text{ nm}$.","$300\\text{ nm}$."],"ans":2,"exp":"Sợi cơ bản $11\\text{ nm}$ cuộn xoắn bậc 2 (với sự tham gia của Histone H1) tạo sợi nhiễm sắc $30\\text{ nm}$, tiếp tục xếp cuộn thành vùng siêu xoắn $300\\text{ nm}$ và chromatid $700\\text{ nm}$."},{"id":"MCQ-CL-025","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc NST","q":"Vùng đầu mút (Telomere) của nhiễm sắc thể sinh vật nhân thực có chức năng sinh học chính là gì?","opts":["Bảo vệ các đầu NST không bị dính vào nhau hoặc bị enzyme phân hủy, giúp duy trì ổn định đầu NST qua các lần phân bào.","Là nơi chứa toàn bộ gen quy định giới tính.","Là nơi tổng hợp trực tiếp các phân tử mRNA mã hóa enzyme.","Là vị trí gắn thoi phân bào trong kỳ giữa."],"ans":0,"exp":"Telomere gồm các trình tự lặp lại giàu G-C (ở người là $5'-\\text{TTAGGG}-3'$) bọc bởi phức hợp shelterin bảo vệ đầu NST khỏi bị nhận nhầm là vết đứt DNA."},{"id":"MCQ-CL-026","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chu kỳ tế bào","q":"Trong chu kỳ tế bào nhân thực bình thường, quá trình nhân đôi phân tử DNA và nhân đôi nhiễm sắc thể (chuyển NST đơn thành NST kép gồm 2 chromatid) diễn ra ở pha nào?","opts":["Kỳ giữa của nguyên phân.","Pha $S$ (pha tổng hợp) của kỳ trung gian.","Pha $G_1$ của kỳ trung gian.","Kỳ sau của nguyên phân."],"ans":1,"exp":"Kỳ trung gian gồm $G_1$ (sinh trưởng, tổng hợp bào quan), $S$ (nhân đôi DNA và trung tử) và $G_2$ (chuẩn bị protein, tubulin cho phân bào M)."},{"id":"MCQ-CL-027","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chu kỳ tế bào","q":"Một số tế bào biệt hóa cao ở người trưởng thành như tế bào thần kinh (neuron) hoặc tế bào cơ tim hầu như không phân chia nữa mà dừng lại ổn định ở trạng thái nào của chu kỳ tế bào?","opts":["Pha $G_0$ (trạng thái nghỉ phân chia).","Kỳ sau giảm phân II.","Kỳ giữa nguyên phân.","Pha $S$ kéo dài vĩnh viễn."],"ans":0,"exp":"Các tế bào rút khỏi chu kỳ phân chia đi vào pha $G_0$; một số tế bào (như tế bào gan) có thể quay lại $G_1$ khi mô bị tổn thương, còn tế bào thần kinh trưởng thành ở lại $G_0$ lâu dài."},{"id":"MCQ-CL-028","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nguyên phân","q":"Trong nguyên phân, các nhiễm sắc thể kép đóng xoắn cực đại, có hình dạng đặc trưng rõ nhất dưới kính hiển vi và xếp thành một hàng trên mặt phẳng xích đạo của thoi phân bào ở kỳ nào?","opts":["Kỳ cuối (Telophase).","Kỳ sau (Anaphase).","Kỳ đầu (Prophase).","Kỳ giữa (Metaphase)."],"ans":3,"exp":"Do co xoắn cực đại và tập trung trên một mặt phẳng ở kỳ giữa, kỳ giữa là thời điểm lý tưởng nhất để quan sát, chụp ảnh lập bộ nhiễm sắc thể đồ (Karyotype)."},{"id":"MCQ-CL-029","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nguyên phân","q":"Đặc điểm phân chia tế bào chất (Cytokinesis) ở kỳ cuối nguyên phân của tế bào thực vật khác với tế bào động vật ở điểm nào?","opts":["Tế bào thực vật thắt màng sinh chất từ ngoài vào trong bằng vòng actin.","Tế bào thực vật hình thành vách ngăn (tấm tế bào) từ trung tâm phát triển ra ngoại vi do có thành cellulose cứng; tế bào động vật thắt màng sinh chất từ ngoài vào trong nhờ vòng co thắt actin-myosin.","Tế bào động vật tạo tấm tế bào từ các túi tiết Golgi.","Tế bào thực vật không bao giờ phân chia tế bào chất."],"ans":1,"exp":"Các túi từ bộ máy Golgi mang tiền chất thành tế bào tập trung ở mặt phẳng xích đạo hợp nhất thành tấm tế bào lớn dần ra nối với thành tế bào mẹ."},{"id":"MCQ-CL-030","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nguyên phân","q":"Xét một loài có bộ NST $2n = 16$. Số nhiễm sắc thể kép và số sợi chromatid có trong một tế bào đang ở kỳ giữa của nguyên phân lần lượt là:","opts":["$16$ NST đơn và $16$ chromatid.","$32$ NST đơn và $32$ chromatid.","$8$ NST kép và $16$ chromatid.","$16$ NST kép và $32$ chromatid."],"ans":3,"exp":"Ở kỳ giữa nguyên phân có $2n = 16$ NST kép; mỗi NST kép gồm 2 chromatid chị em nên tổng số chromatid $= 4n = 32$."},{"id":"MCQ-CL-031","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nguyên phân","q":"Một tế bào sinh dưỡng bình thường của ngô ($2n = 20$) tiến hành nguyên phân liên tiếp $4$ lần. Tổng số tế bào con tạo ra và số tế bào con mới hoàn toàn được bổ sung thêm sau quá trình là:","opts":["$16$ tế bào con và $16$ tế bào mới hoàn toàn.","$16$ tế bào con và $15$ tế bào mới được tạo thêm.","$32$ tế bào con và $31$ tế bào mới.","$8$ tế bào con và $7$ tế bào mới."],"ans":1,"exp":"Số tế bào con sau $k=4$ lần nguyên phân là $2^4 = 16$ tế bào; so với 1 tế bào ban đầu, số tế bào mới tăng thêm là $16 - 1 = 15$."},{"id":"MCQ-CL-032","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nguyên phân","q":"Ý nghĩa sinh học quan trọng nhất của quá trình nguyên phân đối với cơ thể đa bào sinh sản hữu tính là gì?","opts":["Tạo ra hiện tượng trao đổi chéo giữa các NST tương đồng.","Tạo ra vô số biến dị tổ hợp trong các giao tử.","Giúp cơ thể sinh trưởng, thay thế tế bào già/tổn thương và truyền đạt ổn định bộ NST lưỡng bội $2n$ qua các thế hệ tế bào soma.","Làm giảm số lượng nhiễm sắc thể đi một nửa còn $n$."],"ans":2,"exp":"Nguyên phân sao chép và chia đều bộ NST $2n$ giúp duy trì tính ổn định di truyền qua các thế hệ tế bào sinh dưỡng và cơ thể sinh sản vô tính."},{"id":"MCQ-CL-033","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Hiện tượng tiếp hợp và trao đổi chéo giữa các nhiễm sắc tử không chị em trong cặp nhiễm sắc thể kép tương đồng xảy ra ở kỳ nào của quá trình giảm phân?","opts":["Kỳ giữa của Giảm phân I.","Kỳ đầu của Giảm phân I (Kỳ đầu I).","Kỳ sau của Giảm phân I.","Kỳ đầu của Giảm phân II."],"ans":1,"exp":"Ở kỳ đầu I (giai đoạn pachytene), các NST tương đồng bắt cặp tạo thể lưỡng trị (bivalent/tetrad) và trao đổi chéo tại các điểm bắt chéo (chiasmata)."},{"id":"MCQ-CL-034","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Sự kiện nào sau đây là điểm khác biệt mấu chốt ở Kỳ giữa Giảm phân I so với Kỳ giữa Nguyên phân?","opts":["Ở kỳ giữa GP I, các cặp NST kép tương đồng xếp thành HAI hàng trên mặt phẳng xích đạo; còn ở kỳ giữa nguyên phân, các NST kép xếp thành MỘT hàng.","Ở kỳ giữa nguyên phân các cặp NST tương đồng tiếp hợp với nhau.","Ở kỳ giữa GP I các NST ở trạng thái đơn.","Ở kỳ giữa GP I không hình thành thoi phân bào."],"ans":0,"exp":"Việc xếp 2 hàng từng cặp NST kép tương đồng ở kỳ giữa GP I là cơ sở vật chất để phân ly độc lập các NST kép có nguồn gốc từ bố và mẹ ở kỳ sau GP I."},{"id":"MCQ-CL-035","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Tại kỳ sau của Giảm phân I, diễn biến nào xảy ra với các nhiễm sắc thể?","opts":["Mỗi nhiễm sắc thể KÉP trong cặp tương đồng tách nhau ra (không chẻ tâm động) và di chuyển về hai cực đối diện của tế bào.","Các nhiễm sắc tử chị em tách nhau ở tâm động thành NST đơn đi về hai cực.","Các NST tập trung thành 1 hàng ở mặt phẳng xích đạo.","Nhân đôi thêm một lần nữa thành $8n$."],"ans":0,"exp":"Ở kỳ sau GP I, tâm động không phân chia: mỗi cực nhận $n$ NST kép, giúp bộ NST giảm đi một nửa từ $2n$ (kép) thành $n$ (kép) sau lần phân bào I."},{"id":"MCQ-CL-036","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Một loài động vật có bộ NST $2n = 24$. Số nhiễm sắc thể đơn và số chromatid trong một tế bào đang ở kỳ sau của Giảm phân II lần lượt là:","opts":["$12$ NST kép và $24$ chromatid.","$24$ NST kép và $48$ chromatid.","$12$ NST đơn và $0$ chromatid.","$24$ NST đơn và $0$ chromatid."],"ans":3,"exp":"Đầu GP II mỗi tế bào có $n = 12$ NST kép. Ở kỳ sau GP II, $12$ NST kép tách tâm động thành $24$ NST đơn phân ly về 2 cực (khi đã tách rời không còn gọi là chromatid nữa nên số chromatid $= 0$)."},{"id":"MCQ-CL-037","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Xét một cơ thể động vật có kiểu gen $AaBbDd$ (các cặp gen nằm trên các cặp NST tương đồng khác nhau). Khi một tế bào sinh tinh duy nhất của cơ thể này giảm phân bình thường (không có trao đổi chéo), số loại tinh trùng thực tế tạo thành từ tế bào đó là bao nhiêu?","opts":["$2$ loại tinh trùng (với tỉ lệ $1:1$).","$8$ loại tinh trùng.","$1$ loại tinh trùng.","$4$ loại tinh trùng."],"ans":0,"exp":"1 tế bào sinh tinh giảm phân không TĐC chỉ có 1 cách xếp hàng ở kỳ giữa I nên chỉ sinh ra $2$ loại tinh trùng (mỗi loại 2 tinh trùng); cả cơ thể mới tạo tối đa $2^3 = 8$ loại."},{"id":"MCQ-CL-038","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Ở một loài có $2n = 8$, có $50$ tế bào sinh tinh giảm phân bình thường tạo tinh trùng. Tổng số tinh trùng tạo thành là bao nhiêu?","opts":["$400$ tinh trùng.","$200$ tinh trùng.","$100$ tinh trùng.","$50$ tinh trùng."],"ans":1,"exp":"Mỗi tế bào sinh tinh giảm phân tạo $4$ tinh trùng $\\Rightarrow 50 \\times 4 = 200$ tinh trùng."},{"id":"MCQ-CL-039","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến cấu trúc NST","q":"Dạng đột biến cấu trúc nhiễm sắc thể nào làm tăng chiều dài của một nhiễm sắc thể, tăng số lượng bản sao của một số gen và thường làm tăng cường hoặc giảm bớt mức độ biểu hiện của tính trạng (ví dụ làm tăng hàm lượng enzyme Amylase ở đại mạch)?","opts":["Đột biến thể một.","Đột biến mất đoạn NST.","Đột biến đảo đoạn NST.","Đột biến lặp đoạn NST."],"ans":3,"exp":"Lặp đoạn làm tăng số lượng gen trên cùng NST, có ý nghĩa lớn trong tiến hóa vì tạo bản sao gen dự phòng để đột biến hình thành gen mới mà không mất chức năng cũ."},{"id":"MCQ-CL-040","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến cấu trúc NST","q":"Dạng đột biến cấu trúc nhiễm sắc thể nào KHÔNG làm thay đổi số lượng gen và hàm lượng DNA trên nhiễm sắc thể, nhưng làm thay đổi trình tự phân bố các gen trên nhiễm sắc thể đó?","opts":["Đột biến đảo đoạn NST (và chuyển đoạn trong phạm vi một NST).","Đột biến đa bội cùng nguồn.","Đột biến mất đoạn NST.","Đột biến lặp đoạn NST."],"ans":0,"exp":"Đảo đoạn chỉ làm đứt một đoạn rồi quay $180^\\circ$ gắn lại vào đúng NST đó nên tổng vật chất di truyền không đổi, nhưng thay đổi trật tự gen và mức độ hoạt động gen."},{"id":"MCQ-CL-041","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến cấu trúc NST","q":"Hội chứng 'tiếng mèo kêu' (Cri-du-chat) ở người với biểu hiện trẻ chậm phát triển trí tuệ, đầu nhỏ và tiếng khóc giống mèo kêu là hậu quả của dạng đột biến NST nào?","opts":["Lặp đoạn trên nhiễm sắc thể số 22.","Thêm một nhiễm sắc thể số 21.","Mất đoạn vai ngắn của nhiễm sắc thể số 5 ($5p^-$).","Mất một nhiễm sắc thể giới tính X."],"ans":2,"exp":"Cri-du-chat là ví dụ kinh điển của đột biến mất đoạn NST ở người (mất đoạn nhánh ngắn NST số 5)."},{"id":"MCQ-CL-042","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến số lượng NST","q":"Một loài thực vật lưỡng bội có bộ NST $2n = 14$. Thể ba ($2n + 1$) và thể không ($2n - 2$) của loài này có số lượng nhiễm sắc thể trong một tế bào sinh dưỡng lần lượt là:","opts":["$28$ NST và $7$ NST.","$15$ NST và $13$ NST.","$21$ NST và $13$ NST.","$15$ NST và $12$ NST."],"ans":3,"exp":"Thể ba: $2n + 1 = 14 + 1 = 15$ NST. Thể không: $2n - 2 = 14 - 2 = 12$ NST."},{"id":"MCQ-CL-043","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến số lượng NST","q":"Trong chọn giống cây trồng, giống dưa hấu không hạt, nho không hạt hoặc chuối nhà ăn quả thường thuộc dạng đột biến số lượng NST nào và vì sao chúng không có hạt?","opts":["Thể tứ bội ($4n$); không hạt do hạt phấn quá lớn.","Thể một ($2n - 1$); không hạt do thiếu toàn bộ tế bào trứng.","Thể song nhị bội ($2n_A + 2n_B$); không hạt do lai xa.","Thể tam bội ($3n$); không hạt do các NST không bắt cặp phân ly đồng đều được ở kỳ đầu/sau Giảm phân I nên giao tử bất thụ."],"ans":3,"exp":"Ở thể đa bội lẻ ($3n$), mỗi nhóm tương đồng có 3 chiếc nên khi giảm phân phân ly hỗn loạn ($1:2$), tạo hầu hết giao tử lệch bội mất cân bằng gen và bất thụ $\\rightarrow$ quả không hạt."},{"id":"MCQ-CL-044","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến số lượng NST","q":"Bệnh nhân mắc hội chứng Down ở người có kiểu hình cổ ngắn, má phệ, khe mắt xếch, chậm phát triển trí tuệ mang bộ nhiễm sắc thể đặc trưng là:","opts":["Có $3$ nhiễm sắc thể số 18.","Có bộ NST $44A + XXY$.","Chỉ có $1$ nhiễm sắc thể số 21 ($2n - 1 = 45$).","Có $3$ nhiễm sắc thể số 21 ($2n + 1 = 47$)."],"ans":3,"exp":"Hội chứng Down là thể ba phổ biến nhất có khả năng sống sót ở người (Trisomy 21), thường phát sinh do không phân ly cặp 21 trong giảm phân ở mẹ (tỉ lệ tăng theo tuổi mẹ)."},{"id":"MCQ-CL-045","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến số lượng NST","q":"So với thể lưỡng bội ($2n$) cùng loài, cơ thể thực vật tự tứ bội ($4n$) thường có đặc điểm hình thái và sinh lý nào sau đây?","opts":["Hàm lượng DNA trong nhân giảm đi một nửa.","Không thể sinh sản bằng con đường sinh dưỡng.","Tế bào to, cơ quan sinh dưỡng (lá, thân, củ, quả) lớn, sinh trưởng mạnh và chống chịu tốt với điều kiện bất lợi.","Kích thước nhỏ bé còi cọc và luôn bất thụ hoàn toàn."],"ans":2,"exp":"Thể đa bội chẵn (như $4n$) có bộ gen tăng gấp bội nên tổng hợp nhiều chất hữu cơ, tế bào to khỏe, cơ quan sinh dưỡng lớn và giảm phân vẫn tạo giao tử $2n$ hữu thụ."},{"id":"MCQ-CL-046","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến số lượng NST","q":"Hóa chất Colchicine thường được sử dụng để xử lý hạt nảy mầm hoặc đỉnh sinh trưởng chồi cây nhằm tạo ra thể tự đa bội. Colchicine tác động vào giai đoạn nào của nguyên phân?","opts":["Phá hủy màng sinh chất ở kỳ cuối.","Ức chế sự hình thành thoi phân bào ở kỳ đầu/kỳ giữa, làm cho toàn bộ các nhiễm sắc thể kép đã nhân đôi không thể phân ly về 2 cực tạo tế bào $4n$.","Cắt đứt tất cả các NST thành từng đoạn ngắn.","Kích thích nhân đôi DNA thêm 3 lần trong pha S."],"ans":1,"exp":"Colchicine gắn vào tiểu phần tubulin ngăn trùng hợp vi ống thoi vô sắc, khiến $2n$ NST kép sau khi tách tâm động thành $4n$ NST đơn không phân ly được mà nằm chung trong 1 nhân mới ($4n$)."},{"id":"MCQ-CL-047","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến số lượng NST","q":"Thể song nhị bội (Allotetraploid) thường được hình thành trong tự nhiên hoặc nhân tạo qua con đường nào?","opts":["Xử lý tia X làm mất đoạn hai nhiễm sắc thể khác nhau.","Cho một cây lưỡng bội tự thụ phấn liên tiếp 10 thế hệ.","Lai xa giữa hai loài khác nhau ($n_A + n_B$) tạo con lai bất thụ, sau đó xảy ra đa bội hóa bộ NST lên thành $2n_A + 2n_B$ hữu thụ.","Dung hợp tinh trùng và tế bào soma của cùng một cá thể."],"ans":2,"exp":"Con lai xa $F_1$ ($n_A + n_B$) bất thụ vì các NST không có cặp tương đồng; sau khi đa bội hóa thành $2n_A + 2n_B$, mỗi NST đều có bạn cặp đôi nên giảm phân tạo giao tử hữu thụ bình thường."},{"id":"MCQ-CL-048","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân bào & Tính toán","q":"Ở cà chua có $2n = 24$. Một hợp tử bình thường tiến hành nguyên phân $3$ đợt liên tiếp. Tổng số tâm động có trong tất cả các tế bào con được tạo thành ở cuối đợt nguyên phân thứ 3 là:","opts":["$96$ tâm động.","$192$ tâm động.","$24$ tâm động.","$384$ tâm động."],"ans":1,"exp":"Sau 3 đợt nguyên phân tạo $2^3 = 8$ tế bào con, mỗi tế bào có $2n = 24$ NST đơn (mỗi NST có 1 tâm động) $\\Rightarrow$ Tổng tâm động $= 8 \\times 24 = 192$."},{"id":"MCQ-CL-049","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân & Thụ tinh","q":"Ở gà ($2n = 78$), một số tế bào sinh tinh tiến hành giảm phân bình thường tạo ra tổng cộng $512$ tinh trùng. Số tế bào sinh tinh ban đầu và tổng số nhiễm sắc thể có trong tất cả các tinh trùng tạo thành lần lượt là:","opts":["$128$ tế bào sinh tinh và $19968$ NST.","$256$ tế bào sinh tinh và $39936$ NST.","$128$ tế bào sinh tinh và $39936$ NST.","$512$ tế bào sinh tinh và $19968$ NST."],"ans":0,"exp":"Số tế bào sinh tinh $= 512 / 4 = 128$. Mỗi tinh trùng có $n = 39$ NST $\\Rightarrow$ Tổng NST $= 512 \\times 39 = 19968$ NST."},{"id":"MCQ-CL-050","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ tế bào TV","q":"Phương pháp nhân giống vô tính hàng loạt cây trồng sạch bệnh từ một mô nhỏ đỉnh sinh trưởng của cây mẹ quý hiếm (như hoa lan, chuối, khoai tây) dựa trên đặc tính nào của tế bào thực vật?","opts":["Tính toàn năng (Totipotency) của tế bào thực vật: mỗi tế bào chứa đầy đủ thông tin di truyền có thể phân chia và biệt hóa lại thành cây hoàn chỉnh trong môi trường thích hợp.","Khả năng tiếp hợp trao đổi chéo trong nguyên phân.","Sự thụ tinh kép đặc trưng của thực vật hạt kín.","Hiện tượng đa bội hóa tự phát trong đất."],"ans":0,"exp":"Nhờ tính toàn năng và sự điều tiết tỉ lệ hormone Auxin/Cytokinin trong nuôi cấy mô (vi nhân giống), mô sẹo tái sinh rễ và chồi tạo hàng nghìn cây con đồng nhất kiểu gen với cây mẹ."},{"id":"MCQ-CL-051","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ tế bào TV","q":"Kỹ thuật dung hợp tế bào trần (tế bào thực vật đã loại bỏ thành Cellulose bằng enzyme Cellulase và Pectinase) giữa hai loài khác nhau (ví dụ khoai tây và cà chua tạo cây 'Pomato') có ưu thế nổi bật nào so với lai hữu tính truyền thống?","opts":["Luôn tạo ra cây chỉ mang bộ gen của loài cho hạt phấn.","Không cần bất kỳ môi trường nuôi cấy vô trùng nào.","Tạo ra được con lai soma chứa bộ NST lưỡng bội của cả hai loài mà vượt qua rào cản cách ly sinh sản khác loài (không cần thụ phấn thụ tinh).","Biến thực vật thành động vật đa bào."],"ans":2,"exp":"Lai tế bào trần dùng xung điện hoặc PEG làm hòa nhập hai tế bào soma trần của 2 loài khác nhau, khắc phục rào cản bất tương hợp phấn - nhụy và bất thụ con lai xa."},{"id":"MCQ-CL-052","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ tế bào ĐV","q":"Trong quy trình nhân bản vô tính động vật tạo cừu Dolly, nhân của tế bào tuyến vú lưỡng bội ($2n$) của cừu mặt trắng được chuyển vào tế bào chất của tế bào trứng (đã loại bỏ nhân) của cừu mặt đen, rồi cấy phôi vào tử cung cừu mặt đen mang thai hộ. Cừu Dolly sinh ra có ngoại hình và hệ gen trong nhân giống con cừu nào?","opts":["Giống cừu mặt đen mang thai hộ.","Giống hệt cừu mặt trắng cho nhân tế bào tuyến vú (cừu mẹ di truyền nhân).","Mang đặc điểm trung gian pha trộn $50\\%$ của hai cừu.","Giống hệt cừu mặt đen cho tế bào chất trứng."],"ans":1,"exp":"Hầu hết các tính trạng hình thái của cơ thể do gen trong nhân quy định, nên cừu Dolly có kiểu gen nhân và ngoại hình giống hệt cừu cho nhân tuyến vú (chỉ có DNA ti thể lấy từ trứng cừu mặt đen)."},{"id":"MCQ-CL-053","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chu kỳ tế bào","q":"Tác nhân gây hại đột biến DNA (như tia X) kích hoạt protein bảo vệ bộ gen $p53$ dừng chu kỳ tế bào ở điểm kiểm soát $G_1/S$ nhằm mục đích gì?","opts":["Cho tế bào có thời gian sửa chữa các hư hỏng DNA trước khi bước vào pha $S$ nhân đôi (hoặc kích hoạt Apoptosis nếu tổn thương không thể sửa).","Thúc đẩy tế bào đi thẳng vào nguyên phân để nhân rộng đột biến.","Loại bỏ toàn bộ màng nhân.","Chuyển tế bào soma thành giao tử đơn bội."],"ans":0,"exp":"Protein $p53$ ('người gác cổng hệ gen') hoạt hóa gen $p21$ ức chế phức hợp CDK-Cyclin làm ngừng chu kỳ ở $G_1$ để sửa chữa DNA, ngăn truyền đột biến cho tế bào con."},{"id":"MCQ-CL-054","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến NST","q":"Trong quần thể tự nhiên của một loài thực vật có $2n = 16$, có thể xuất hiện tối đa bao nhiêu dạng đột biến thể ba ($2n + 1$) khác nhau về nhiễm sắc thể bị thừa?","opts":["$15$ dạng.","$8$ dạng.","$16$ dạng.","$28$ dạng."],"ans":1,"exp":"Loài có $2n = 16 \\Rightarrow n = 8$ cặp NST tương đồng khác nhau $\\Rightarrow$ Có tối đa $8$ dạng thể ba đơn ($2n+1$)."},{"id":"MCQ-CL-055","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân bào & Thụ tinh","q":"Một tế bào sinh trứng có kiểu gen $AaBbDd$ giảm phân bình thường (không có trao đổi chéo). Thực tế tế bào sinh trứng này tạo ra được bao nhiêu loại trứng?","opts":["$4$ loại trứng.","$2$ loại trứng.","$8$ loại trứng.","$1$ loại trứng duy nhất."],"ans":3,"exp":"Một tế bào sinh trứng giảm phân chỉ tạo ra DUY NHẤT 1 tế bào trứng (và 3 thể cực tiêu biến), nên thực tế chỉ thu được 1 loại trứng."},{"id":"MCQ-CL-056","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân bào","q":"Trong quá trình phân bào nguyên phân bình thường, màng nhân và nhân con biến mất ở kỳ nào và tái xuất hiện trở lại ở kỳ nào?","opts":["Biến mất ở pha S và tái xuất hiện ở pha G2.","Tồn tại nguyên vẹn không bao giờ biến mất trong suốt nguyên phân.","Biến mất ở kỳ giữa và tái xuất hiện ở kỳ sau.","Biến mất ở cuối kỳ đầu (kỳ trước) và tái xuất hiện ở kỳ cuối."],"ans":3,"exp":"Ở kỳ đầu muộn (prometaphase), lamin nhân bị phosphoryl hóa làm màng nhân phân mảnh để vi ống thoi phân bào tiếp cận NST; ở kỳ cuối, màng nhân tái lập quanh hai bộ NST mới."},{"id":"MCQ-CL-057","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Nếu quá trình giảm phân ở một cơ thể lưỡng bội $2n$ diễn ra bình thường tạo giao tử $n$, điều nào sau đây KHÔNG đúng khi nói về ý nghĩa của Giảm phân kết hợp Thụ tinh?","opts":["Giữ nguyên chính xác kiểu gen đồng hợp giống hệt thế hệ bố mẹ ban đầu ở mọi cá thể con.","Tạo ra nguồn biến dị tổ hợp phong phú nhờ phân ly độc lập, trao đổi chéo và thụ tinh ngẫu nhiên.","Cung cấp nguyên liệu thứ cấp vô cùng đa dạng cho tiến hóa và chọn giống.","Duy trì ổn định bộ NST $2n$ đặc trưng của loài qua các thế hệ sinh sản hữu tính."],"ans":0,"exp":"Giảm phân và thụ tinh làm TÁI TỔ HỢP vật chất di truyền tạo con cái đa dạng di truyền khác bố mẹ (không giữ nguyên hoàn toàn như sinh sản vô tính/nguyên phân)."},{"id":"MCQ-CL-058","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến cấu trúc","q":"Dạng đột biến cấu trúc nhiễm sắc thể nào làm thay đổi số lượng gen giữa các nhiễm sắc thể không tương đồng (làm nhóm gen liên kết từ NST này chuyển sang nằm trên NST khác)?","opts":["Đột biến lặp đoạn trên chính NST đó.","Đột biến mất $1$ cặp nucleotide.","Đột biến đảo đoạn quanh tâm động.","Đột biến chuyển đoạn giữa các NST không tương đồng."],"ans":3,"exp":"Chuyển đoạn tương hỗ hoặc không tương hỗ giữa 2 NST khác cặp làm thay đổi thành phần nhóm gen liên kết của cả hai NST."},{"id":"MCQ-CL-059","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hội chứng NST người","q":"Xét nghiệm tế bào ối của một thai nhi cho kết quả bộ nhiễm sắc thể gồm $44$ NST thường và $3$ NST giới tính ($XXX$ - Hội chứng Siêu nữ / Triple X). Tổng số nhiễm sắc thể trong một tế bào sinh dưỡng của thai nhi này là bao nhiêu?","opts":["$47$ NST (thuộc dạng thể ba $2n + 1$).","$46$ NST.","$69$ NST (thể tam bội).","$45$ NST (thuộc dạng thể một $2n - 1$)."],"ans":0,"exp":"Người bình thường có $44A + XX$ ($46$ NST). Cá thể $44A + XXX$ có $47$ NST (thừa 1 NST X ở cặp giới tính)."},{"id":"MCQ-CL-060","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hội chứng NST người","q":"Một người nam mắc hội chứng Klinefelter có bộ NST $44A + XXY$. Kết luận nào sau đây là chính xác về giới tính và khả năng sinh sản thường gặp của người này?","opts":["Bị thiếu một nhiễm sắc thể số 21.","Mang kiểu hình nữ hoàn toàn do có 2 NST X.","Mang kiểu hình nam (do có NST Y chứa gen <i>SRY</i>), nhưng thường cao gầy, tinh hoàn nhỏ kém phát triển và vô sinh (hoặc suy giảm sinh tinh nặng).","Luôn chết ngay ở giai đoạn phôi thai."],"ans":2,"exp":"Ở người và động vật có vú, sự có mặt của NST Y (gen <i>SRY</i>) quy định phát triển tinh hoàn và giới tính nam bất kể có bao nhiêu NST X; nhưng thừa 1 X làm teo ống sinh tinh và rối loạn nội tiết."},{"id":"MCQ-CL-061","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chu kỳ tế bào","q":"Phức hợp $\\text{MPF}$ (Maturation Promoting Factor - yếu tố thúc đẩy phân bào) kích hoạt tế bào vượt qua điểm kiểm soát $G_2/M$ để bước vào nguyên phân có cấu tạo gồm hai thành phần nào?","opts":["DNA polymerase và Helicase.","Histone H1 và Nucleosome.","Actin và Myosin.","Enzyme Kinase phụ thuộc Cyclin (Cdk1) và tiểu phần điều hòa Cyclin B."],"ans":3,"exp":"Nồng độ Cyclin B tăng dần trong pha S và $G_2$, kết hợp với Cdk1 (nồng độ hằng định) tạo phức hợp MPF hoạt động kích hoạt phân giải màng nhân và co xoắn NST."},{"id":"MCQ-CL-062","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nguyên phân","q":"Một tế bào sinh dục sơ khai ($2n = 10$) nguyên phân một số lần liên tiếp tạo ra các tế bào con. Biết môi trường nội bào đã cung cấp nguyên liệu tương đương với $310$ nhiễm sắc thể đơn. Số lần nguyên phân của tế bào đó là:","opts":["$4$ lần.","$5$ lần.","$6$ lần.","$3$ lần."],"ans":1,"exp":"$\\text{NST}_{mt} = 1 \\times 2n \\times (2^k - 1) = 10(2^k - 1) = 310 \\Rightarrow 2^k - 1 = 31 \\Rightarrow 2^k = 32 \\Rightarrow k = 5$ lần."},{"id":"MCQ-CL-063","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Ở một loài có $2n = 18$, một tế bào đang ở kỳ sau của Giảm phân I. Trong tế bào này đang có bao nhiêu NST kép và bao nhiêu tâm động?","opts":["$36$ NST đơn và $36$ tâm động.","$18$ NST đơn và $36$ tâm động.","$9$ NST kép và $9$ tâm động.","$18$ NST kép và $18$ tâm động."],"ans":3,"exp":"Ở kỳ sau GP I, các NST kép tách khỏi cặp tương đồng đi về 2 cực nhưng chưa tách tâm động, nên trong 1 tế bào vẫn có đủ $2n = 18$ NST kép và $18$ tâm động."},{"id":"MCQ-CL-064","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến NST","q":"Loài lúa mì trồng hiện đại (<i>Triticum aestivum</i>) có bộ NST lục bội $2n = 6x = 42$ được hình thành qua quá trình lai xa và đa bội hóa liên tiếp giữa 3 loài lưỡng bội khác nhau (mỗi loài có $2n = 14$). Số lượng NST trong mỗi tế bào hạt phấn (giao tử đực $n$) bình thường của loài lúa mì này là bao nhiêu?","opts":["$42$ NST.","$21$ NST.","$7$ NST.","$14$ NST."],"ans":1,"exp":"Lúa mì lục bội là thể dị đa bội hữu thụ ($2n = 6x = 42 = 2n_A + 2n_B + 2n_D$), khi giảm phân bình thường tạo giao tử chứa $n = 3x = 21$ NST ($7_A + 7_B + 7_D$)."},{"id":"MCQ-CL-065","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giao tử & Đa bội","q":"Một cây tứ bội có kiểu gen $AAAA$ giảm phân bình thường tạo giao tử $2n$. Tỉ lệ các loại giao tử tạo ra là:","opts":["$50\\% AA : 50\\% Aa$.","$100\\%$ giao tử $AA$.","$100\\%$ giao tử $A$.","$25\\% AA : 50\\% Aa : 25\\% aa$."],"ans":1,"exp":"Cơ thể đồng hợp tử tứ bội $AAAA$ khi giảm phân cho $100\\%$ giao tử lưỡng bội $AA$."},{"id":"MCQ-CL-066","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến NST","q":"Nguyên nhân chủ yếu dẫn đến đột biến lệch bội (thể một $2n-1$, thể ba $2n+1$) trong tự nhiên là gì?","opts":["Do lai giữa hai dòng thuần chủng cùng loài.","Do mất 1 cặp nucleotide trên phân tử mRNA.","Do toàn bộ các cặp NST đều không phân ly cùng lúc.","Do tác nhân vật lý, hóa học hoặc rối loạn nội bào làm thoi phân bào không gắn hoặc không kéo được một hoặc một vài cặp NST phân ly trong giảm phân hoặc nguyên phân."],"ans":3,"exp":"Không phân ly một (hoặc một vài) cặp NST trong giảm phân tạo giao tử $n+1$ và $n-1$; thụ tinh với giao tử $n$ tạo thể ba ($2n+1$) hoặc thể một ($2n-1$)."},{"id":"MCQ-CL-067","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Giảm phân","q":"Trong quá trình sinh trứng ở người phụ nữ, sự phân chia tế bào chất không đều ở Giảm phân I và Giảm phân II tạo ra $1$ tế bào trứng lớn giàu chất dinh dưỡng và $3$ thể cực nhỏ tiêu biến. Ý nghĩa tiến hóa của sự phân bào bất đối xứng này là gì?","opts":["Giúp loại bỏ toàn bộ ty thể ra khỏi trứng.","Tập trung tối đa chất dinh dưỡng, bào quan và mRNA dự trữ của noãn bào vào duy nhất một tế bào trứng để nuôi phôi phát triển ở những giai đoạn đầu sau thụ tinh.","Giúp tạo ra số lượng trứng nhiều gấp 4 lần tinh trùng.","Đảm bảo trứng có bộ NST $4n$."],"ans":1,"exp":"Hợp tử trong những ngày đầu trước khi làm tổ hoàn toàn phụ thuộc bào tương, mRNA dự trữ và ti thể của trứng; phân chia lệch giúp bảo tồn trọn vẹn nguồn dự trữ đó cho 1 tế bào trứng."},{"id":"MCQ-CL-068","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc NST","q":"Trong bộ nhiễm sắc thể lưỡng bội của một loài động vật ($2n$), hai nhiễm sắc thể của cùng một cặp tương đồng ở trạng thái chưa nhân đôi có đặc điểm nào sau đây?","opts":["Luôn có trình tự nucleotide giống hệt nhau $100\\%$ ở mọi gen.","Một chiếc ở trong nhân, một chiếc ở ngoài ti thể.","Chỉ tồn tại trong các giao tử đơn bội.","Giống nhau về hình dạng, kích thước, vị trí tâm động và mang cùng trật tự các locus gen (một chiếc có nguồn gốc từ bố, một chiếc từ mẹ)."],"ans":3,"exp":"Cặp NST tương đồng có cùng bộ locus gen ở các vị trí tương ứng (tuy có thể mang các alen khác nhau như $A$ và $a$), một chiếc nhận từ tinh trùng bố và một chiếc từ trứng mẹ."},{"id":"MCQ-CL-069","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Nguyên phân & Kết hợp","q":"Có $4$ tế bào sinh dục sơ khai của một loài ($2n = 16$) tiến hành nguyên phân liên tiếp một số lần bằng nhau tạo ra tất cả $128$ tế bào con. Sau đó $50\\%$ số tế bào con này đi vào giảm phân tạo tinh trùng (hiệu suất thụ tinh của tinh trùng là $12.5\\%$). Tổng số NST môi trường cung cấp cho cả quá trình nguyên phân - giảm phân và số hợp tử tạo thành lần lượt là:","opts":["$2048$ NST và $32$ hợp tử.","$1984$ NST và $64$ hợp tử.","$3008$ NST và $64$ hợp tử.","$3008$ NST và $32$ hợp tử."],"ans":3,"exp":"Số lần NP: $4 \\times 2^k = 128 \\Rightarrow 2^k = 32 \\Rightarrow k = 5$. $\\text{NST}_{NP} = 4 \\times 16 \\times (32 - 1) = 1984$. Có $64$ tế bào giảm phân cần $\\text{NST}_{GP} = 64 \\times 16 = 1024 \\Rightarrow$ Tổng NST $= 1984 + 1024 = 3008$. Số tinh trùng $= 64 \\times 4 = 256$; số hợp tử $= 256 \\times 12.5\\% = 32$."},{"id":"MCQ-CL-070","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giao tử TĐC","q":"Một loài thực vật có bộ NST $2n = 10$ ($n = 5$ cặp NST tương đồng), tất cả các cặp NST đều chứa nhiều cặp gen dị hợp tử. Khi cơ thể giảm phân, có $1$ cặp NST xảy ra trao đổi chéo tại $1$ điểm, $1$ cặp NST xảy ra trao đổi chéo tại $2$ điểm không cùng lúc và $3$ cặp NST còn lại không xảy ra trao đổi chéo. Số loại giao tử tối đa có thể tạo ra từ cơ thể này là:","opts":["$128$ loại.","$192$ loại.","$64$ loại.","$96$ loại."],"ans":1,"exp":"3 cặp không TĐC cho $2^3 = 8$; 1 cặp TĐC 1 điểm cho $4$ loại; 1 cặp TĐC 2 điểm không cùng lúc cho $6$ loại (tổng quát $2^{n + m_1} \\cdot 3^{m_2} = 2^{5+1} \\cdot 3^1 = 192$ loại)."},{"id":"MCQ-CL-071","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tế bào sinh tinh","q":"Một cơ thể động vật có kiểu gen $AaBbDd\\frac{EG}{eg}$ tiến hành giảm phân. Giả sử chỉ có $3$ tế bào sinh tinh của cơ thể này tham gia giảm phân bình thường và đều KHÔNG xảy ra trao đổi chéo giữa $E$ và $G$. Số loại tinh trùng tối đa thu được từ $3$ tế bào này là:","opts":["$8$ loại.","$12$ loại.","$16$ loại.","$6$ loại."],"ans":3,"exp":"Mỗi tế bào sinh tinh không TĐC chỉ tạo tối đa $2$ loại tinh trùng. Với $k = 3$ tế bào, số loại tối đa $= \\min(2k, 2^4) = \\min(6, 16) = 6$ loại."},{"id":"MCQ-CL-072","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tế bào sinh tinh","q":"Có $5$ tế bào sinh tinh của một cơ thể có kiểu gen $Aa\\frac{BD}{bd}$ giảm phân bình thường, trong đó có $2$ tế bào xảy ra trao đổi chéo giữa $B$ và $D$, còn $3$ tế bào không xảy ra trao đổi chéo. Tổng số loại tinh trùng tối đa có thể thu được từ $5$ tế bào này là (biết tối đa cả kiểu gen tạo $8$ loại tinh trùng):","opts":["$12$ loại.","$10$ loại.","$14$ loại.","$8$ loại."],"ans":3,"exp":"Cơ thể $Aa\\frac{BD}{bd}$ chỉ có tối đa $2 \\times 4 = 8$ loại tinh trùng! $2$ tế bào TĐC có thể tạo tối đa $2 \\times 4 = 8$ loại và $3$ tế bào không TĐC góp phần nằm trong $8$ loại đó, nên bị chặn trên bởi tổng lý thuyết là $8$ loại!"},{"id":"MCQ-CL-073","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giao tử Đa bội 4n","q":"Một cây tứ bội có kiểu gen $AAaaBBbb$ (hai cặp gen phân ly độc lập) giảm phân bình thường chỉ tạo giao tử $2n$ hữu thụ. Tỉ lệ loại giao tử mang ít nhất $1$ alen trội ở mỗi gen (tức giao tử chứa cả $A$ và $B$) của cây này là:","opts":["$\\frac{35}{36}$.","$\\frac{16}{36}$.","$\\frac{25}{36}$.","$\\frac{1}{36}$."],"ans":2,"exp":"$AAaa$ tạo $(\\frac{5}{6}\\text{ mang }A : \\frac{1}{6}aa)$; $BBbb$ tạo $(\\frac{5}{6}\\text{ mang }B : \\frac{1}{6}bb)$. Tỉ lệ giao tử chứa cả $A$ và $B = \\frac{5}{6} \\times \\frac{5}{6} = \\frac{25}{36}$."},{"id":"MCQ-CL-074","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Lai thể đa bội 4n","q":"Cho phép lai giữa cây tứ bội và cây lưỡng bội: $P: AAaa \\times Aa$ (biết cây $4n$ tạo giao tử $2n$, cây $2n$ tạo giao tử $n$, tất cả các hợp tử $3n$ đều sống và $A$ trội hoàn toàn so với $a$). Tỉ lệ kiểu hình ở đời con $F_1$ là:","opts":["$11$ trội : $1$ lặn.","$3$ trội : $1$ lặn.","$35$ trội : $1$ lặn.","$5$ trội : $1$ lặn."],"ans":0,"exp":"$AAaa$ cho $\\frac{1}{6}aa$; $Aa$ cho $\\frac{1}{2}a \\Rightarrow$ Kiểu hình lặn $aaa = \\frac{1}{6} \\times \\frac{1}{2} = \\frac{1}{12} \\Rightarrow$ Tỉ lệ kiểu hình $= 11$ trội : $1$ lặn."},{"id":"MCQ-CL-075","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Lai thể đa bội 4n","q":"Cho phép lai $P: AAaaBbbb \\times AaaaBBbb$ (các gen PLĐL, giảm phân bình thường tạo giao tử $2n$ hữu thụ). Tỉ lệ cá thể ở $F_1$ đồng hợp lặn cả hai tính trạng ($aaaabbbb$) và tỉ lệ cá thể mang kiểu hình trội cả hai tính trạng lần lượt là:","opts":["$\\frac{1}{144}$ và $\\frac{121}{144}$.","$\\frac{1}{144}$ và $\\frac{143}{144}$.","$\\frac{1}{72}$ và $\\frac{35}{36}$.","$\\frac{1}{36}$ và $\\frac{25}{36}$."],"ans":0,"exp":"Cặp $A$: $AAaa (\\frac{1}{6}aa) \\times Aaaa (\\frac{1}{2}aa) \\Rightarrow aaaa = \\frac{1}{12}$, trội $A--- = \\frac{11}{12}$. Cặp $B$: $Bbbb (\\frac{1}{2}bb) \\times BBbb (\\frac{1}{6}bb) \\Rightarrow bbbb = \\frac{1}{12}$, trội $B--- = \\frac{11}{12}$. Suy ra $aaaabbbb = \\frac{1}{144}$ và trội 2 tính trạng $= \\frac{11}{12} \\times \\frac{11}{12} = \\frac{121}{144}$."},{"id":"MCQ-CL-076","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Lệch bội 2n+1","q":"Ở một loài thực vật, gen $A$ (thân cao) trội hoàn toàn so với $a$ (thân thấp). Lai giữa hai cây thể ba cùng có kiểu gen $AAa \\times Aaa$. Biết hạt phấn $n+1$ không có khả năng thụ tinh (chỉ hạt phấn $n$ thụ tinh), còn noãn $n$ và $n+1$ thụ tinh bình thường; đồng thời $AAa$ làm bố. Đời con $F_1$ thu được tỉ lệ kiểu hình là:","opts":["$35$ cao : $1$ thấp.","$5$ cao : $1$ thấp.","$11$ cao : $1$ thấp.","$17$ cao : $1$ thấp."],"ans":1,"exp":"Bố $AAa$ chỉ dùng hạt phấn đơn bội ($\\frac{2}{3}A : \\frac{1}{3}a$). Mẹ $Aaa$ tạo noãn $(\\frac{1}{6}A : \\frac{2}{6}a : \\frac{2}{6}Aa : \\frac{1}{6}aa) \\Rightarrow$ tổng giao tử mang toàn alen lặn của mẹ ($a + aa$) $= \\frac{2}{6} + \\frac{1}{6} = \\frac{1}{2}$. Do đó tỉ lệ cây thấp ($aa + aaa$) $= \\frac{1}{3} \\times \\frac{1}{2} = \\frac{1}{6} \\Rightarrow 5$ cao : $1$ thấp."},{"id":"MCQ-CL-077","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chu kỳ tế bào & Nguyên phân","q":"Đo hàm lượng DNA trong một tế bào ở các pha khác nhau của chu kỳ tế bào thu được: Pha $G_1$ có $4\\text{ pg}$ DNA. Nếu nuôi cấy một quần thể tế bào đồng bộ hóa bắt đầu từ $G_1$ rồi bổ sung Aphidicolin (chất ức chế đặc hiệu DNA polymerase $\\alpha/\\delta$), hầu hết các tế bào sẽ bị dừng lại ở vị trí nào và hàm lượng DNA trong nhân lúc đó là bao nhiêu?","opts":["Dừng lại ở kỳ giữa với $8\\text{ pg}$ DNA.","Dừng lại ở kỳ cuối với $2\\text{ pg}$ DNA.","Dừng lại ngay đầu/trong pha $S$ với hàm lượng DNA xấp xỉ $4\\text{ pg}$ (chưa thể nhân đôi lên $8\\text{ pg}$).","Vẫn tiếp tục giảm phân tạo tế bào $2\\text{ pg}$."],"ans":2,"exp":"Aphidicolin khóa tổng hợp DNA ở pha $S$ nên tế bào bị kẹt tại ranh giới $G_1/S$ hoặc đầu pha $S$ (phương pháp đồng bộ hóa tế bào) với lượng DNA giữ nguyên quanh mức $2C = 4\\text{ pg}$."},{"id":"MCQ-CL-078","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thời gian các pha Chu kỳ TB","q":"Một dòng tế bào động vật nuôi cấy có thời gian chu kỳ tế bào tổng cộng là $24\\text{ giờ}$. Khi đếm ngẫu nhiên $1000$ tế bào đang sinh trưởng mạnh dưới kính hiển vi, người ta thấy có $50$ tế bào đang ở pha nguyên phân $M$ (gồm $20$ tế bào kỳ đầu, $15$ kỳ giữa, $5$ kỳ sau, $10$ kỳ cuối). Thời gian ước tính của pha $M$ và riêng Kỳ giữa trong chu kỳ tế bào này lần lượt là:","opts":["Pha $M = 5.0\\text{ giờ}$ và Kỳ giữa $= 1.5\\text{ giờ}$.","Pha $M = 2.4\\text{ giờ}$ và Kỳ giữa $= 0.72\\text{ giờ}$.","Pha $M = 1.2\\text{ giờ}$ ($72\\text{ phút}$) và Kỳ giữa $= 0.36\\text{ giờ}$ ($21.6\\text{ phút}$).","Pha $M = 0.5\\text{ giờ}$ và Kỳ giữa $= 0.15\\text{ giờ}$."],"ans":2,"exp":"Tỉ lệ thời gian một pha tương ứng tỉ lệ số tế bào bắt gặp ở pha đó trong quần thể không đồng bộ: $t_M = \\frac{50}{1000} \\times 24 = 1.2\\text{ giờ}$ ($72\\text{ phút}$); $t_{\\text{giữa}} = \\frac{15}{1000} \\times 24 = 0.36\\text{ giờ}$ ($21.6\\text{ phút}$)."},{"id":"MCQ-CL-079","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chu kỳ tế bào & Phóng xạ","q":"Để xác định thời gian của pha $G_2$ ở tế bào rễ hành, người ta ủ rễ hành trong môi trường có chứa $^3\\text{H}$-Thymidine (đồng vị phóng xạ chỉ gắn vào DNA đang nhân đôi ở pha $S$) trong $15\\text{ phút}$, rồi rửa sạch và chuyển sang môi trường thường. Sau bao lâu kể từ lúc ủ thì ta bắt đầu quan sát thấy các NST mang dấu phóng xạ xuất hiện đầu tiên ở Kỳ giữa của nguyên phân?","opts":["Đúng bằng tổng thời gian của cả chu kỳ tế bào ($G_1 + S + G_2 + M$).","Ngay lập tức sau $0\\text{ phút}$.","Đúng bằng thời gian của pha $G_1$.","Đúng bằng thời gian của pha $G_2$ cộng thêm khoảng thời gian từ đầu Kỳ đầu đến Kỳ giữa."],"ans":3,"exp":"Những tế bào vừa ở cuối pha $S$ hấp thụ $^3\\text{H}$-Thymidine sẽ đi hết pha $G_2$ rồi bước vào pha $M$ (kỳ đầu $\\rightarrow$ kỳ giữa), nên thời gian chờ chính là $t_{G2} + t_{\\text{đầu}}$."},{"id":"MCQ-CL-080","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thoi phân bào & Thuốc ung thư","q":"Thuốc điều trị ung thư Paclitaxel (Taxol) có cơ chế tác động đối lập với Colchicine: Colchicine ngăn cản sự trùng hợp tạo vi ống, còn Taxol gắn chặt vào vi ống để ỔN ĐỊNH HÓA chúng và ngăn cản sự giải trùng hợp (co ngắn) của vi ống. Tại sao dù có tác dụng trái ngược nhau lên sự bền vững vi ống, cả Colchicine và Taxol đều làm tế bào ung thư dừng phân chia ở nguyên phân?","opts":["Vì Taxol hòa tan hoàn toàn DNA của tế bào ung thư.","Vì Taxol phá hủy ribosome 80S.","Vì sự di chuyển NST về mặt phẳng xích đạo và đặc biệt là sự kéo tách chromatid ở kỳ sau đòi hỏi vi ống thể động phải liên tục lắp ghép VÀ tháo dỡ (tính bất ổn định động); khóa cứng vi ống khiến tế bào không vượt qua điểm kiểm soát thoi phân bào.","Vì Taxol biến tế bào ung thư thành tế bào vi khuẩn."],"ans":2,"exp":"Ở kỳ sau nguyên phân, các vi ống thể động phải giải trùng hợp (rút ngắn) để kéo NST đơn về 2 cực. Taxol làm đóng băng vi ống nên thoi phân bào tê liệt và tế bào bị đẩy vào Apoptosis."},{"id":"MCQ-CL-081","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phân bào & Ung thư","q":"Trong thử nghiệm nuôi cấy các tế bào sợi bình thường của người trên đĩa Petri chứa đầy đủ môi trường dinh dưỡng, khi các tế bào phân chia phủ kín thành một lớp đơn trên bề mặt đĩa thì chúng tự động ngừng phân chia. Nếu xuất hiện một tế bào chuyển dạng ác tính (ung thư) trên đĩa đó, hiện tượng nào sẽ xảy ra?","opts":["Các tế bào ung thư biến đổi thành lớp vỏ cellulose.","Tế bào ung thư tự chết theo Apoptosis ngay khi chạm thành đĩa.","Tế bào ung thư ngừng phân chia vĩnh viễn khi chạm vào tế bào lân cận.","Tế bào ung thư bị mất khả năng 'ức chế tiếp xúc' (Contact inhibition) và mất tính phụ thuộc neo bám, tiếp tục phân chia chồng chất lên nhau tạo thành khối nhiều lớp (foci)."],"ans":3,"exp":"Tế bào bình thường có cơ chế ức chế phụ thuộc mật độ/tiếp xúc (Density-dependent inhibition) và phụ thuộc neo bám (Anchorage dependence); tế bào ung thư mất cả hai cơ chế kiểm soát này."},{"id":"MCQ-CL-082","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến điểm vs Đột biến NST","q":"So sánh giữa một đột biến mất đoạn nhỏ gồm 500 cặp nucleotide ở vùng giữa của một NST với một đột biến đảo đoạn dài 5 triệu cặp nucleotide trên chính NST đó, phát biểu nào sau đây đúng?","opts":["Đảo đoạn dài có thể làm thay đổi vị trí tương đối của hàng loạt gen (và gây rối loạn giảm phân khi ở dạng dị hợp), còn mất đoạn 500 cặp nu nếu rơi vào vùng mã hóa của 1 gen thiết yếu có thể gây chết ngay ở trạng thái đồng hợp.","Mất đoạn nhỏ luôn vô hại 100% còn đảo đoạn luôn gây chết ngay.","Đảo đoạn làm thay đổi hàm lượng DNA trong nhân tế bào.","Chỉ mất đoạn mới quan sát được dễ dàng dưới kính hiển vi quang học còn đảo đoạn lớn thì không bao giờ thấy."],"ans":0,"exp":"Kích thước không quyết định hoàn toàn mức độ nghiêm trọng: mất đoạn làm mất hẳn thông tin di truyền, còn đảo đoạn bảo toàn hàm lượng DNA nhưng thay đổi trật tự gen và gây tạo giao tử bất thường khi trao đổi chéo."},{"id":"MCQ-CL-083","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến cấu trúc & Tiến hóa","q":"Trong quá trình tiến hóa của loài người so với các loài vượn người (Tinh tinh, Gorilla, Đười ươi có $2n = 48$), tại sao bộ nhiễm sắc thể lưỡng bội của loài người chỉ còn $2n = 46$ nhưng hàm lượng DNA lại tương đương?","opts":["Do toàn bộ gen của 2 NST tổ tiên bị tiêu hủy.","Do người có bộ NST đơn bội là 46.","Do loài người đã bị mất vĩnh viễn 1 cặp nhiễm sắc thể thể không ($2n - 2$).","Do trong nhánh tiến hóa dẫn tới loài người đã xảy ra một sự kiện dung hợp đầu - đầu (chuyển đoạn dung hợp) giữa hai cặp NST tổ tiên tạo thành nhiễm sắc thể số $2$ của người ngày nay (vẫn còn dấu vết trình tự Telomere nằm ở giữa và dấu vết tâm động thứ hai bất hoạt trên NST số 2)."],"ans":3,"exp":"NST số 2 ở người là bằng chứng tế bào học tuyệt đẹp của tiến hóa: có vết tích Telomere hợp nhất ở băng $2q13$ và 1 tâm động thoái hóa ứng với NST 2A và 2B ở tinh tinh."},{"id":"MCQ-CL-084","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Lệch bội & Chẩn đoán trước sinh","q":"Khi thực hiện xét nghiệm Karyotype từ tế bào thai nhi lấy qua chọc dò dịch ối ở tuần thai thứ 16, kỹ thuật viên nuôi cấy tế bào ối rồi dùng hóa chất nào để tích lũy thật nhiều tế bào đang dừng ở Kỳ giữa, sau đó xử lý dung dịch nhược trương để làm bung tách các NST giúp chụp ảnh đếm chính xác?","opts":["Penicillin để phá vỡ thành cellulose.","Actinomycin D để ức chế phiên mã.","2,4-DNP để phá màng trong ti thể.","Colchicine (hoặc Colcemid) để khóa tế bào ở Kỳ giữa nguyên phân khi NST co xoắn cực đại rõ nhất."],"ans":3,"exp":"Trong lập công thức NST (Karyotyping), Phytohemagglutinin (PHA) kích thích phân bào, Colcemid/Colchicine chặn thoi phân bào giữ tế bào tại Kỳ giữa, rồi dung dịch KCl nhược trương làm trương màng giải phóng chùm NST trải phẳng lên lam kính."},{"id":"MCQ-CL-085","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Công nghệ tế bào & Nuôi cấy","q":"Trong nuôi cấy mô thực vật, để điều chỉnh hướng biệt hóa của mô sẹo (Callus) sao cho kích thích mạnh sự ra CHỒI (chồi ngọn phát triển) trước rồi mới chuyển sang môi trường ra RỄ, người ta cần điều chỉnh tỉ lệ nồng độ hai loại phytohormone nào?","opts":["Môi trường ra chồi có tỉ lệ $\\text{Cytokinin} / \\text{Auxin}$ CAO; môi trường ra rễ có tỉ lệ $\\text{Auxin} / \\text{Cytokinin}$ CAO.","Chỉ dùng Ethylene để tạo chồi và rễ đồng thời.","Chỉ dùng Acid Abscisic (ABA) cho cả hai giai đoạn.","Môi trường ra chồi cần tỉ lệ $\\text{Auxin} / \\text{Cytokinin}$ cao; ra rễ cần $\\text{Cytokinin}$ cao."],"ans":0,"exp":"Thí nghiệm kinh điển của Skoog và Miller: tỉ lệ Cytokinin cao hơn Auxin kích thích hình thành chồi; tỉ lệ Auxin cao hơn Cytokinin kích thích ra rễ; tỉ lệ cân bằng duy trì mô sẹo phân chia vô định hình."},{"id":"MCQ-CL-086","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Rối loạn Giảm phân","q":"Xét một cặp bố mẹ bình thường đều có kiểu gen dị hợp về một cặp gen trên NST thường: $Aa \\times Aa$. Trong giảm phân ở mẹ, cặp NST mang gen này KHÔNG phân ly ở Giảm phân I ở $20\\%$ số tế bào sinh trứng; ở bố giảm phân bình thường. Tỉ lệ hợp tử mang kiểu gen $AAa$ được tạo ra ở đời con là bao nhiêu?","opts":["$5\\%$.","$20\\%$.","$2.5\\%$.","$10\\%$."],"ans":0,"exp":"Ở mẹ ($Aa$), $20\\%$ tế bào rối loạn GP I tạo ra $10\\%$ trứng $Aa$ và $10\\%$ trứng $O$. Bố ($Aa$) tạo $\\frac{1}{2}A : \\frac{1}{2}a$. Do đó tỉ lệ hợp tử $AAa = 10\\% \\text{ (trứng } Aa) \\times 50\\% \\text{ (tinh trùng } A) = 5\\%$."},{"id":"MCQ-CL-087","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Rối loạn Giảm phân","q":"Một cơ thể có kiểu gen $Aa$ giảm phân tạo giao tử, giả sử có $16\\%$ số tế bào sinh tinh xảy ra sự không phân ly của cặp NST mang gen $Aa$ ở Giảm phân II ở CẢ HAI tế bào con sinh ra từ GP I (hoặc tính riêng từng tế bào: cụ thể trong $16\\%$ tế bào sinh tinh đó, cặp NST kép $AA$ không phân ly ở GP II còn cặp $aa$ phân ly bình thường). Tỉ lệ loại tinh trùng mang kiểu gen $AA$ tạo ra trong tổng số tinh trùng là bao nhiêu?","opts":["$16\\%$.","$4\\%$.","$8\\%$.","$2\\%$."],"ans":1,"exp":"1 tế bào sinh tinh có $AA$ không phân ly ở GP II và $aa$ bình thường tạo ra: $1$ tinh trùng $AA$, $1$ tinh trùng $O$ và $2$ tinh trùng $a$ (tức tinh trùng $AA$ chiếm $\\frac{1}{4}$ sản phẩm của tế bào bị rối loạn đó). Với $16\\%$ tế bào bị rối loạn như vậy $\\Rightarrow$ Tỉ lệ tinh trùng $AA = 16\\% \\times \\frac{1}{4} = 4\\%$."},{"id":"MCQ-CL-088","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Nguyên phân & Bất thường","q":"Nếu sự không phân ly của cặp NST giới tính $XY$ xảy ra ở LẦN NGUYÊN PHÂN ĐẦU TIÊN của hợp tử mang kiểu gen $XY$ (2 chromatid của $X$ hoặc $Y$ không phân ly) — ví dụ một NST Y kép không tách nhau ở kỳ sau nguyên phân đầu tiên — hai phôi bào đầu tiên tạo thành sẽ có bộ NST giới tính là:","opts":["Cả hai phôi bào đều là $XXY$.","Một phôi bào là $XYY$ ($2n + 1$) và một phôi bào là $X$ ($2n - 1$, tức $XO$), phát triển thành cơ thể thể khảm $XO/XYY$.","Một phôi bào $XXY$ và một phôi bào $YO$ đều phát triển bình thường.","Tất cả tế bào của cơ thể đều là $XYY$."],"ans":1,"exp":"Khi 2 chromatid $Y$ cùng đi về 1 cực ở lần nguyên phân đầu tiên của hợp tử $XY$ (trong khi $X$ phân ly bình thường), cực thứ nhất nhận $X + YY = XYY$, cực thứ hai chỉ nhận $X + O = XO$, tạo cá thể khảm $45,X / 47,XYY$."},{"id":"MCQ-CL-089","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giảm phân & Cây trồng","q":"Ở dưa hấu lưỡng bội có $2n = 22$. Để sản xuất hạt giống dưa hấu tam bội không hạt ($3n = 33$) cung cấp cho nông dân, các nhà chọn giống thực hiện lai giữa hai cây bố mẹ có bộ NST như thế nào?","opts":["Dùng cây mẹ tứ bội ($4n = 44$) lai với cây bố lưỡng bội ($2n = 22$) để thu được hạt lai tam bội ($3n = 33$) trên quả của cây $4n$.","Dùng cây thể một ($2n-1$) tự thụ phấn.","Dùng cây lưỡng bội ($2n$) lai với cây đơn bội ($n$).","Dùng cây tam bội ($3n$) tự thụ phấn liên tục."],"ans":0,"exp":"Cây $4n$ làm mẹ kết hợp hạt phấn từ cây $2n$ làm bố tạo phôi $3n$ hữu lực. Khi gieo hạt $3n$ thành cây trưởng thành, cây $3n$ ra hoa thụ phấn bởi phấn của cây $2n$ (trồng xen để kích thích tạo hormone phát triển bầu quả) sẽ cho quả dưa hấu tam bội không hạt."},{"id":"MCQ-CL-090","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thể đơn bội kép","q":"Ưu điểm vượt trội nhất của phương pháp nuôi cấy hạt phấn/noãn chưa thụ tinh kết hợp lưỡng bội hóa bằng Colchicine so với phương pháp tự thụ phấn nhiều thế hệ để tạo dòng thuần chủng ở cây giao phấn là gì?","opts":["Chỉ sau 1 thế hệ đã tạo ra ngay được các dòng thuần chủng đồng hợp tử tuyệt đối về TẤT CẢ các cặp gen, kể cả các gen lặn có lợi vốn khó bộc lộ nhanh bằng lai hữu tính, giúp rút ngắn nhiều năm chọn giống.","Tạo ra giống cây tam bội hoàn toàn không có hạt.","Tạo ra các dòng cây có độ dị hợp tử đạt $100\\%$ để khai thác ưu thế lai trực tiếp.","Làm tăng tần số đột biến gen lên gấp 1000 lần."],"ans":0,"exp":"Nuôi hạt phấn đơn bội ($n$) thành mô/cây đơn bội rồi gây lưỡng bội hóa ($2n$) cho ra các dòng đồng hợp tử hoàn toàn ($100\\%$) tại mọi locus chỉ trong 1 thế hệ duy nhất."},{"id":"MCQ-CL-091","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến Mất đoạn & Giả trội","q":"Ở ngô, alen $A$ (hạt màu tím) trội hoàn toàn so với $a$ (hạt màu trắng). Khi lấy hạt phấn của cây thuần chủng hạt tím ($AA$) đã xử lý chiếu xạ tia X để thụ phấn cho cây hạt trắng ($aa$), phần lớn hạt thu được ở $F_1$ có màu tím, nhưng xuất hiện một số ít hạt lại có màu trắng. Giải thích nào hợp lý nhất nếu biết không có thụ phấn nhầm?","opts":["Hạt phấn mang thêm 1 NST chứa $A$ (thể ba).","Tia X đã gây đột biến MẤT ĐOẠN NST mang alen trội $A$ trong hạt phấn, khiến hợp tử chỉ còn mang duy nhất alen lặn $a$ từ mẹ nên biểu hiện kiểu hình lặn (hiện tượng giả trội).","Do đột biến chuyển thành thể tứ bội $AAaa$.","Tia X đã biến alen $a$ thành $A$ ở cây mẹ."],"ans":1,"exp":"Mất đoạn NST mang alen trội $A$ làm mất khả năng che lấp alen lặn $a$ trên chiếc NST tương đồng bình thường còn lại — hiện tượng biểu hiện tính trạng lặn khi chỉ có 1 alen lặn gọi là Giả trội (Pseudodominance)."},{"id":"MCQ-CL-092","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc NST & Euchromatin","q":"Khi quan sát nhân tế bào sinh dưỡng ở kỳ trung gian dưới kính hiển vi điện tử, chất nhiễm sắc chia làm hai vùng: Vùng đồng nhiễm sắc (Euchromatin) bắt màu nhạt, giãn xoắn và Vùng dị nhiễm sắc (Heterochromatin) bắt màu đậm, đóng xoắn chặt. Nhận định nào đúng về đặc điểm phiên mã của hai vùng này?","opts":["Chỉ có vùng dị nhiễm sắc mới chứa các gen mã hóa enzyme đường phân.","Vùng dị nhiễm sắc phiên mã mạnh gấp 10 lần vùng đồng nhiễm sắc.","Các gen đang phiên mã tích cực tập trung chủ yếu ở vùng đồng nhiễm sắc (Euchromatin); còn vùng dị nhiễm sắc (tâm động, telomere, thể Barr) đóng xoắn chặt và hầu như KHÔNG có hoạt động phiên mã.","Vùng đồng nhiễm sắc bị bất hoạt hoàn toàn ở kỳ trung gian."],"ans":2,"exp":"Cấu trúc đóng chặt của dị nhiễm sắc (nhờ Histone khử acetyl và methyl hóa H3K9me3/H3K27me3) ngăn cản RNA polymerase và yếu tố phiên mã tiếp cận DNA."},{"id":"MCQ-CL-093","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giảm phân & Phóng xạ","q":"Nuôi một tế bào sinh tinh có $2n = 8$ ở pha $G_1$ trong môi trường bình thường (chứa Thymidine thường), sau đó chuyển sang môi trường có chứa $^{3}\\text{H}$-Thymidine phóng xạ để tế bào đi qua pha $S$ chuẩn bị cho Giảm phân, rồi thực hiện trọn vẹn Giảm phân tạo $4$ tinh trùng. Kết thúc giảm phân, có bao nhiêu tinh trùng mang dấu phóng xạ $^{3}\\text{H}$?","opts":["Cả $4$ tinh trùng đều mang dấu phóng xạ trên TẤT CẢ các nhiễm sắc thể của chúng.","Chỉ có $1$ tinh trùng mang dấu phóng xạ.","Không có tinh trùng nào mang dấu phóng xạ.","Chỉ có $2$ tinh trùng mang dấu phóng xạ."],"ans":0,"exp":"Trước khi giảm phân, tế bào chỉ nhân đôi DNA 1 lần duy nhất tại pha $S$ (trong môi trường $^{3}\\text{H}$-Thymidine). Theo nguyên tắc bán bảo toàn, mọi NST đơn trong tất cả chromatid đều mang 1 mạch cũ và 1 mạch mới chứa $^{3}\\text{H}$, nên cả 4 tinh trùng đều có phóng xạ."},{"id":"MCQ-CL-094","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Nguyên phân & Thụ tinh ở Thực vật","q":"Ở thực vật hạt kín (như cây lúa $2n = 24$), quá trình thụ tinh kép diễn ra trong túi phôi tạo nên Phôi và Nội nhũ. Một hạt lúa đang nảy mầm có số lượng nhiễm sắc thể trong một tế bào rễ non (thuộc phôi) và một tế bào nội nhũ lần lượt là:","opts":["$12$ NST trong tế bào rễ và $24$ NST trong tế bào nội nhũ.","$12$ NST trong tế bào rễ và $36$ NST trong tế bào nội nhũ.","$24$ NST trong tế bào rễ và $36$ NST trong tế bào nội nhũ.","$24$ NST trong tế bào rễ và $48$ NST trong tế bào nội nhũ."],"ans":2,"exp":"Thụ tinh kép: 1 tinh tử ($n=12$) thụ tinh với noãn ($n=12$) tạo hợp tử phát triển thành phôi $2n=24$; tinh tử thứ hai ($n=12$) hợp nhất với nhân cực lưỡng bội ($n+n=24$) tạo tế bào nội nhũ tam bội $3n=36$."},{"id":"MCQ-CL-095","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến NST & Lai xa","q":"Khi lai hai loài thực vật khác nhau có bộ NST lưỡng bội lần lượt là Loài I ($2n = 16$) và Loài II ($2n = 18$), thu được con lai $F_1$ bất thụ, sau đó xử lý Colchicine gây đa bội hóa thành công thu được thể song nhị bội hữu thụ. Một tế bào đang ở kỳ giữa của lần Giảm phân I của thể song nhị bội này có bao nhiêu nhiễm sắc thể kép?","opts":["$68$ NST kép.","$17$ NST kép.","$34$ NST kép.","$18$ NST kép."],"ans":2,"exp":"Thể song nhị bội có $2n = 2n_I + 2n_{II} = 16 + 18 = 34$ NST. Ở kỳ giữa Giảm phân I, tất cả các NST đã nhân đôi thành $34$ NST kép xếp thành $17$ cặp tương đồng trên mặt phẳng xích đạo."},{"id":"MCQ-CL-096","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đa bội & Chọn giống","q":"Trong tự nhiên, sự xuất hiện các loài thực vật đa bội mới (tự đa bội hoặc dị đa bội) diễn ra đặc biệt phổ biến hơn hẳn ở thực vật so với ở động vật bậc cao (như thú, chim). Nguyên nhân sinh học chính giải thích sự khác biệt này là gì?","opts":["Thực vật thường lưỡng tính (tự thụ phấn được), có khả năng sinh sản sinh dưỡng mạnh, và không có cơ chế xác định giới tính nghiêm ngặt bằng cặp NST giới tính $XX/XY$ như động vật (nơi đa bội hóa làm rối loạn cân bằng liều lượng gen xác định giới tính và gây chết phôi).","DNA của thực vật không có chứa liên kết Hydrogen.","Động vật bậc cao luôn mang bộ NST $4n$ sẵn có.","Động vật không có quá trình nguyên phân hay giảm phân."],"ans":0,"exp":"Ở thú, bất hoạt NST X và cân bằng liều NST giới tính/NST thường cực kỳ chặt chẽ khiến thể tam bội/tứ bội đều chết phôi hoặc vô sinh, còn thực vật lưỡng tính và sinh sản sinh dưỡng cho phép thể đa bội vượt qua nút thắt sinh sản."},{"id":"MCQ-CL-097","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến Lệch bội","q":"Ở một loài động vật ($2n = 12$), xét cặp NST số 1 có kiểu gen $Aa$. Trong quá trình giảm phân ở cơ thể cái, có $10\\%$ số tế bào bị rối loạn không phân ly cặp NST số 1 ở Giảm phân I (các cặp khác bình thường); cơ thể đực ($Aa$) giảm phân hoàn toàn bình thường. Xác suất để hợp tử tạo ra từ cặp bố mẹ này mang kiểu gen $AAa$ hoặc $Aaa$ (thể ba ở cặp số 1 mang cả hai loại alen) là bao nhiêu?","opts":["$2.5\\%$.","$5\\%$.","$1.25\\%$.","$10\\%$."],"ans":1,"exp":"Mẹ rối loạn GP I tạo $5\\%$ trứng $Aa$ và $5\\%$ trứng $O$. Bố bình thường tạo $50\\%$ tinh trùng $A$ và $50\\%$ tinh trùng $a$. Trứng $Aa$ ($5\\%$) kết hợp tinh trùng $A$ ($50\\%$) tạo $AAa$ ($2.5\\%$) và kết hợp tinh trùng $a$ ($50\\%$) tạo $Aaa$ ($2.5\\%$). Tổng $= 2.5\\% + 2.5\\% = 5\\%$."},{"id":"MCQ-CL-098","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điểm kiểm soát & Phân bào","q":"Trong nguyên phân, điểm kiểm soát Thoi phân bào (Spindle Assembly Checkpoint - SAC) tại chuyển tiếp từ Kỳ giữa sang Kỳ sau hoạt động như một phanh hãm cực kỳ chặt chẽ. Tín hiệu nào kích hoạt phanh hãm của điểm kiểm soát SAC và khiến tế bào CHƯA thể bước vào Kỳ sau?","opts":["Màng nhân đã hình thành hoàn chỉnh quanh 2 cực.","Quá trình nhân đôi DNA vừa mới kết thúc ở pha S.","Còn bất kỳ một thể động (Kinetochore) nào của nhiễm sắc thể kép chưa gắn đúng vào dây tơ vô sắc từ hai cực (chưa đạt lực căng cân bằng), khiến protein Mad2 ức chế phức hợp APC/C.","Tất cả các NST đã xếp thẳng hàng trên mặt phẳng xích đạo và gắn đủ lực căng."],"ans":2,"exp":"Chừng nào còn 1 NST lạc chưa gắn hai cực, phức hợp MCC (chứa Mad2, BubR1) khóa cứng phức hợp thúc đẩy kỳ sau (APC/C-Cdc20), ngăn không cho enzyme Separase cắt protein Cohesin giữ hai chromatid chị em."},{"id":"MCQ-CL-099","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phân bào & Cohesin","q":"Tại sao trong Giảm phân I, các nhiễm sắc tử chị em KHÔNG tách rời nhau ở tâm động khi tiến vào Kỳ sau I (dù dọc cánh tay đã tách nhau tại các điểm chiasma), mà phải đợi đến Kỳ sau Giảm phân II mới tách nhau?","opts":["Vì tâm động chỉ được tổng hợp mới vào kỳ giữa GP II.","Vì ở Giảm phân I hoàn toàn không có enzyme Separase trong tế bào.","Vì ở Giảm phân I không có phức hợp Cohesin dọc cánh tay NST.","Nhờ protein Shugoshin ($\\text{SGO1}$) bảo vệ đặc hiệu phức hợp Cohesin ở vùng TÂM ĐỘNG khỏi bị enzyme Separase cắt bỏ ở kỳ sau GP I; đến kỳ sau GP II Shugoshin biến mất cho phép Separase cắt đứt Cohesin tâm động."],"ans":3,"exp":"Ở kỳ sau GP I, Separase chỉ cắt Cohesin dọc cánh tay NST để giải phóng các điểm bắt chéo chiasma cho cặp tương đồng phân ly, còn Cohesin quanh tâm động được Shugoshin ('thần hộ mệnh') bảo vệ tới tận GP II."},{"id":"MCQ-CL-100","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Số kiểu giao tử & Giới hạn TB","q":"Một cơ thể thực vật có kiểu gen $AaBbDdEeGg$ (5 cặp gen nằm trên 5 cặp NST khác nhau). Giả sử chỉ lấy $6$ tế bào sinh hạt phấn (tế bào sinh tinh) của cơ thể này cho giảm phân bình thường tạo tinh tử. Số loại tinh tử (giao tử đực) tối thiểu và tối đa thu được từ $6$ tế bào trên lần lượt là:","opts":["Tối thiểu $1$ loại; tối đa $32$ loại.","Tối thiểu $6$ loại; tối đa $24$ loại.","Tối thiểu $4$ loại; tối đa $16$ loại.","Tối thiểu $2$ loại; tối đa $12$ loại."],"ans":3,"exp":"Các gen PLĐL không có TĐC (hoặc TĐC 1 cặp dị hợp vẫn như không vì mỗi cặp chỉ dị hợp 1 gen): mỗi tế bào sinh tinh tạo đúng $2$ loại tinh trùng. Nếu cả $6$ tế bào đều sắp xếp giống nhau thì tối thiểu tạo $2$ loại; nếu cả $6$ tế bào sắp xếp khác nhau đôi một thì tối đa tạo $6 \\times 2 = 12$ loại (vẫn nhỏ hơn tổng $2^5 = 32$)."},{"id":"MCQ-CL-101","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hàm lượng DNA & NST","q":"Đồ thị hàm lượng DNA nhân của một tế bào lưỡng bội đi qua trọn vẹn quá trình Giảm phân bình thường bắt đầu từ pha $G_1$ với lượng DNA bằng $2C$, biến thiên lần lượt qua các giai đoạn $G_1 \\rightarrow S \\rightarrow \\text{Kỳ giữa I} \\rightarrow \\text{Kỳ cuối I (mỗi TB con)} \\rightarrow \\text{Kỳ giữa II} \\rightarrow \\text{Giao tử}$ theo trình tự giá trị nào?","opts":["$1C \\rightarrow 2C \\rightarrow 4C \\rightarrow 2C \\rightarrow 1C \\rightarrow 1C$.","$2C \\rightarrow 4C \\rightarrow 4C \\rightarrow 2C \\rightarrow 2C \\rightarrow 1C$.","$2C \\rightarrow 2C \\rightarrow 4C \\rightarrow 2C \\rightarrow 1C \\rightarrow 1C$.","$2C \\rightarrow 4C \\rightarrow 2C \\rightarrow 1C \\rightarrow 1C \\rightarrow 0.5C$."],"ans":1,"exp":"Tại pha $S$, DNA nhân đôi từ $2C \\rightarrow 4C$; giữ mức $4C$ qua $G_2$, đầu/giữa/sau GP I; kết thúc GP I chia đôi còn $2C$ trong mỗi tế bào con (dù NST chỉ còn $n$ nhưng ở trạng thái kép); kết thúc GP II chia đôi lần nữa còn $1C$ trong giao tử."},{"id":"MCQ-CL-102","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đa bội 4n & Tạp giao","q":"Trong một quần thể thực vật tứ bội ($4n$), xét phép lai $P: AAaa \\times aaaa$. Để đời con $F_1$ thu được tỉ lệ kiểu gen $AAaa$ bằng bao nhiêu (biết giảm phân bình thường tạo giao tử $2n$ hữu thụ)?","opts":["$\\frac{4}{6}$ ($66.67\\%$).","$\\frac{1}{12}$.","$\\frac{1}{3}$.","$\\frac{1}{6}$ ($16.67\\%$)."],"ans":3,"exp":"$AAaa$ tạo giao tử $(\\frac{1}{6}AA : \\frac{4}{6}Aa : \\frac{1}{6}aa)$; cây $aaaa$ chỉ tạo $100\\% aa$. Tổ hợp $AAaa$ ở $F_1$ chỉ hình thành từ $AA (\\frac{1}{6}) \\times aa (1) = \\frac{1}{6}$."},{"id":"MCQ-CL-103","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến Mất đoạn & Giao tử","q":"Ở một loài thực vật ($2n = 12$), một cây mang đột biến mất đoạn nhỏ trên một chiếc NST số 1 (kiểu gen dị hợp về mất đoạn). Biết hạt phấn mang NST mất đoạn hoàn toàn mất khả năng thụ tinh (chết), trong khi noãn mang NST mất đoạn vẫn thụ tinh bình thường nhưng sức sống bằng $50\\%$ so với noãn bình thường. Nếu cho cây này giao phấn với cây bình thường (làm bố), tỉ lệ cây mang đột biến mất đoạn ở đời con là bao nhiêu?","opts":["$\\frac{1}{3}$ ($33.33\\%$).","$\\frac{1}{4}$ ($25\\%$).","$0\\%$.","$\\frac{1}{2}$ ($50\\%$)."],"ans":0,"exp":"Cây mất đoạn làm mẹ tạo 2 loại noãn theo tỉ lệ sống sót: $1$ noãn bình thường : $0.5$ noãn mất đoạn $\\Rightarrow \\frac{2}{3}$ noãn bình thường : $\\frac{1}{3}$ noãn mất đoạn. Bố bình thường cho $100\\%$ hạt phấn bình thường $\\Rightarrow$ Đời con mang mất đoạn chiếm $\\frac{1}{3}$."},{"id":"MCQ-CL-104","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Công nghệ Tế bào","q":"Khi nhân giống vô tính bằng nuôi cấy mô đỉnh sinh trưởng để thu cây sạch virus từ một giống khoai tây quý bị nhiễm virus toàn thân, tại sao người ta chỉ tách một mẩu mô rất nhỏ (khoảng $0.1 - 0.5\\text{ mm}$) ngay tại chóp đỉnh sinh trưởng (mô phân sinh ngọn) để nuôi cấy?","opts":["Vì đỉnh sinh trưởng có bộ NST $4n$ kháng mọi loại virus.","Vì các tế bào ở chóp đỉnh sinh trưởng phân chia rất nhanh và vùng này chưa hình thành hệ thống mạch dẫn (mạch rây) hoàn chỉnh, nên tốc độ phân bào vượt qua tốc độ nhân lên và di chuyển của virus, giúp vùng đỉnh ngọn hầu như không nhiễm virus.","Vì đỉnh sinh trưởng tự tiết kháng sinh Penicillin tiêu diệt virus.","Vì tế bào đỉnh sinh trưởng có thành tế bào làm bằng Chitin ngăn virus."],"ans":1,"exp":"Vi nhân giống đỉnh sinh trưởng (Meristem tip culture) kết hợp xử lý nhiệt là kỹ thuật chuẩn để phục tráng giống khoai tây, mía, hoa cúc, lan sạch virus."},{"id":"MCQ-CL-105","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giảm phân & Cặp NST giới tính","q":"Ở châu chấu, cơ chế xác định giới tính theo kiểu con cái $XX$, con đực $XO$ (bộ NST của châu chấu cái $2n = 24$, châu chấu đực $2n = 23$). Trong một tế bào sinh tinh của châu chấu đực đang ở kỳ giữa của Giảm phân II, số lượng NST kép có thể quan sát thấy là bao nhiêu?","opts":["Luôn luôn là $23$ NST đơn.","$12$ NST kép (nhóm chứa X) hoặc $11$ NST kép (nhóm không chứa X).","$24$ NST kép ở mọi tế bào.","Luôn luôn là $12$ NST kép."],"ans":1,"exp":"Châu chấu đực có $22A + XO$ ($23$ NST). Kết thúc GP I, chiếc X đi về một cực nên tạo ra 2 tế bào con bước vào GP II: một tế bào có $11A + X = 12$ NST kép, tế bào kia có $11A + O = 11$ NST kép."},{"id":"MCQ-CL-106","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến Số lượng & Tam bội","q":"Ở một loài thực vật lưỡng bội ($2n = 12$), người ta phát hiện một cá thể có số lượng NST trong tế bào sinh dưỡng là $18$ NST. Cơ chế chính xác nào KHÔNG thể là nguyên nhân tạo ra cá thể có $18$ NST này?","opts":["Trong giảm phân của bố hoặc mẹ, toàn bộ bộ NST không phân ly tạo giao tử $2n=12$ kết hợp với giao tử $n=6$.","Cả bố và mẹ đều giảm phân bình thường tạo giao tử $n=6$ rồi thụ tinh bình thường.","Lấy tế bào sinh dưỡng lưỡng bội lai dung hợp tế bào trần với một tế bào đơn bội từ hạt phấn rồi tái sinh cây.","Trong quá trình thụ tinh, $2$ tinh trùng đơn bội ($n=6$) cùng xâm nhập và thụ tinh đồng thời cho $1$ noãn đơn bội ($n=6$)."],"ans":1,"exp":"Cá thể có $18$ NST ứng với thể tam bội $3n = 18$. Hai giao tử bình thường $n=6$ thụ tinh với nhau chỉ cho ra cơ thể $2n=12$, không thể tạo $3n=18$."},{"id":"MCQ-CL-107","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Lệch bội & Xác suất","q":"Ở người, nguyên nhân phổ biến nhất dẫn đến sinh con mắc hội chứng Down (thừa 1 NST số 21) tăng mạnh theo độ tuổi của người mẹ (đặc biệt trên 35 tuổi) là gì?","opts":["Các tế bào noãn sơ cấp của người phụ nữ đã bước vào Kỳ đầu I từ trong bào thai và dừng treo ở trạng thái tiếp hợp kéo dài hàng chục năm cho đến khi rụng trứng; theo thời gian, phức hợp protein Cohesin giữ các cặp NST tương đồng thoái hóa dần làm tăng nguy cơ không phân ly cặp 21.","Do tế bào trứng người phụ nữ tự nhân đôi DNA thêm 1 lần ở tuổi 35.","Do phụ nữ lớn tuổi bắt đầu ngừng nguyên phân ở da.","Do tinh trùng của người bố bị mất toàn bộ NST số 21."],"ans":0,"exp":"Tuổi tác tế bào trứng ở người kéo dài bằng đúng tuổi đời người mẹ (15-45 năm dừng ở Diplotene của Kỳ đầu I), làm suy giảm protein Cohesin và giám sát thoi phân bào, dễ gây sai sót phân ly NST ở GP I."},{"id":"MCQ-CL-108","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chuyển đoạn & Giảm phân","q":"Một người nam mang đột biến chuyển đoạn tương hỗ cân bằng giữa một phần vai dài của NST số 3 và NST số 7. Người này có kiểu hình hoàn toàn bình thường nhưng cặp vợ chồng gặp tình trạng sảy thai liên tiếp nhiều lần. Nguyên nhân di truyền hợp lý nhất là gì?","opts":["Đột biến chuyển đoạn làm người chồng mang bộ NST $3n$.","Người chồng hoàn toàn không thể tạo ra bất kỳ tinh trùng nào.","Toàn bộ tinh trùng của người chồng chỉ mang NST Y.","Người chồng vẫn đủ lượng gen nên bình thường, nhưng trong giảm phân 4 NST ($3, 3', 7, 7'$) bắt cặp chữ thập và thường xảy ra kiểu phân ly liền kề (Adjacent-1 hoặc Adjacent-2) tạo ra tỉ lệ cao tinh trùng bị thừa/thiếu đoạn NST gây chết phôi sớm."],"ans":3,"exp":"Người mang chuyển đoạn cân bằng không mất vật chất di truyền nên khỏe mạnh, nhưng khi giảm phân tạo khoảng $50\\%$ giao tử mất cân bằng (lặp đoạn này - mất đoạn kia), dẫn đến sảy thai hoặc sinh con dị tật."},{"id":"MCQ-CL-109","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phân bào & Sinh trứng","q":"Ở một loài động vật có bộ NST $2n = 24$. Có $15$ tế bào sinh dục cái sơ khai nguyên phân liên tiếp $4$ lần, sau đó $25\\%$ số tế bào con tạo thành phát triển thành tế bào sinh trứng thực hiện giảm phân tạo trứng. Tổng số trứng tạo thành và tổng số thể cực (thể định hướng) tiêu biến lần lượt là:","opts":["$60$ trứng và $60$ thể cực.","$120$ trứng và $360$ thể cực.","$60$ trứng và $180$ thể cực.","$240$ trứng và $720$ thể cực."],"ans":2,"exp":"Số tế bào con sau nguyên phân $= 15 \\times 2^4 = 240$. Số tế bào sinh trứng $= 240 \\times 25\\% = 60$. Mỗi tế bào sinh trứng tạo $1$ trứng và $3$ thể cực $\\Rightarrow 60$ trứng và $180$ thể cực."},{"id":"MCQ-CL-110","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cơ chế Đa bội hóa","q":"Nếu cho cây lưỡng bội có kiểu gen $Aa$ (bố) giao phấn với cây lưỡng bội $Aa$ (mẹ). Giả sử trong giảm phân của cây mẹ có $100\\%$ tế bào bị xử lý ức chế thoi phân bào ngay trong Giảm phân I (tạo toàn bộ noãn $2n$ mang kiểu gen $Aa$), còn cây bố giảm phân bình thường. Tỉ lệ cây con tam bội ($3n$) có kiểu hình lặn ($aaa$) ở đời $F_1$ là bao nhiêu?","opts":["$25\\%$.","$50\\%$.","$0\\%$ (vì tất cả hợp tử đều mang kiểu gen $AAa$ hoặc $Aaa$).","$12.5\\%$."],"ans":2,"exp":"Mẹ tạo $100\\%$ noãn lưỡng bội $Aa$ (luôn mang $1$ alen trội $A$). Bố tạo $50\\% A : 50\\% a$. Hợp tử thu được gồm $50\\% AAa : 50\\% Aaa$, do đó $100\\%$ đều biểu hiện kiểu hình trội!"},{"id":"MCQ-CL-111","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thể đa bội & Củ, Quả","q":"So sánh hàm lượng tinh bột và kích thước tế bào của củ cải đường tam bội ($3n = 27$) với củ cải đường lưỡng bội ($2n = 18$), vì sao giống củ cải đường $3n$ thường cho năng suất củ và lượng đường thu hoạch vượt trội hơn hẳn giống $2n$ và $4n$?","opts":["Vì tế bào củ cải $3n$ không có thành cellulose.","Vì giống $3n$ nhân đôi nhanh gấp 10 lần giống $2n$.","Vì giống $3n$ có kích thước tế bào to hơn $2n$, sinh trưởng mạnh và không tốn năng lượng dinh dưỡng nuôi hoa/hạt (do $3n$ bất thụ không tạo hạt), dồn toàn bộ chất hữu cơ tích lũy vào củ.","Vì giống $3n$ có khả năng tự cố định đạm từ không khí."],"ans":2,"exp":"Cây tam bội vừa có hiệu ứng tăng liều gen (tế bào to, quang hợp mạnh) vừa bất thụ hữu tính nên không tiêu hao sản phẩm quang hợp vào kết hạt, tối ưu hóa tích trữ vào củ/quả."},{"id":"MCQ-CL-112","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chu kỳ tế bào & Phóng xạ","q":"Một tế bào lưỡng bội ($2n = 12$) có tổng lượng DNA nhân ở pha $G_1$ là $8\\text{ pg}$ và có chứa $24$ chromatid ở một thời điểm phân bào nào đó. Kết luận chính xác nhất về trạng thái và pha phân bào của tế bào lúc quan sát là:","opts":["Đang ở pha $G_2$, kỳ đầu nguyên phân, kỳ giữa nguyên phân hoặc kỳ đầu/giữa Giảm phân I (tất cả đều có $2n=12$ NST kép, $24$ chromatid và $16\\text{ pg}$ DNA).","Đang ở kỳ sau nguyên phân với $24$ chromatid.","Đang ở pha $G_1$ với $24$ chromatid.","Đang ở kỳ giữa Giảm phân II với $24$ chromatid."],"ans":0,"exp":"Mỗi tế bào lưỡng bội $2n=12$ có $24$ chromatid khi và chỉ khi có $12$ NST ở trạng thái KÉP ($4C = 16\\text{ pg}$ DNA), tương ứng khoảng từ sau pha $S$ ($G_2$) đến kỳ giữa NP hoặc kỳ đầu/giữa/sau GP I."},{"id":"MCQ-CL-113","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến Cấu trúc & Tiến hóa","q":"Vì sao trong quần thể tự nhiên của nhiều loài động thực vật, các cá thể dị hợp tử về <strong>đột biến đảo đoạn</strong> lại thường góp phần duy trì các tổ hợp gen thích nghi liên kết chặt với nhau (gọi là 'siêu gen' - Supergene)?","opts":["Vì đảo đoạn làm biến mất hoàn toàn tâm động.","Vì đảo đoạn làm nhân đôi số lượng toàn bộ các gen trên NST.","Vì ở cá thể dị hợp đảo đoạn, các sản phẩm trao đổi chéo đơn bên trong vòng đảo đoạn tạo ra các giao tử bất thường bị chết, khiến chỉ có các giao tử KHÔNG tái tổ hợp mới sống sót (đảo đoạn đóng vai trò chất kìm hãm trao đổi chéo hiệu quả).","Vì đảo đoạn ngăn không cho nhiễm sắc thể đi vào nhân."],"ans":2,"exp":"Đảo đoạn dị hợp không ngăn cản vật lý sự trao đổi chéo, nhưng triệt tiêu toàn bộ sản phẩm tái tổ hợp trong vùng đảo, nhờ đó giữ nguyên vẹn các tổ hợp alen đồng thích nghi ('supergene') như ở bướm giả dạng hay chim sẻ cổ trắng."},{"id":"MCQ-CL-114","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đảo đoạn quanh tâm động","q":"Xét một cá thể dị hợp tử về đột biến <strong>Đảo đoạn quanh tâm động</strong> (Pericentric inversion: đoạn đảo có chứa tâm động ở giữa, ví dụ NST chuẩn $A B \\bullet C D E$ và NST đảo đoạn $A D \\bullet C B E$, với dấu $\\bullet$ là tâm động). Nếu xảy ra một trao đổi chéo đơn bên trong vòng đảo đoạn (giữa $C$ và $D$) ở kỳ đầu Giảm phân I, sản phẩm nhiễm sắc tử tái tổ hợp thu được sẽ có đặc điểm gì?","opts":["Tạo ra 4 nhiễm sắc tử hoàn toàn cân bằng gen và hữu thụ $100\\%$.","Tạo ra 1 nhiễm sắc tử có 2 tâm động và 1 mảnh không có tâm động.","Làm cả hai nhiễm sắc thể đều bị mất tâm động.","Mỗi nhiễm sắc tử tái tổ hợp vẫn chỉ có ĐÚNG $1$ tâm động (không tạo cầu 2 tâm động hay mảnh không tâm động), nhưng bị <strong>lặp một đoạn đầu này và mất một đoạn đầu kia</strong> (ví dụ $A B \\bullet C D A$ và $E B \\bullet C D E$), gây chết giao tử hoặc phôi bất cân bằng."],"ans":3,"exp":"Cần phân biệt rõ 2 loại đảo đoạn ở cấp độ HSG: Đảo đoạn NGOÀI tâm động (Paracentric) tạo cầu 2 tâm động + mảnh không tâm động; Đảo đoạn QUANH tâm động (Pericentric) tạo 2 chromatid đơn tâm động nhưng mang đồng thời cả mất đoạn và lặp đoạn ở hai đầu mút."},{"id":"MCQ-CL-115","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chuyển đoạn Robertson","q":"Dạng đột biến chuyển đoạn Robertson là sự dung hợp tâm giữa hai nhiễm sắc thể tâm đầu (acrocentric - ở người gồm 5 cặp $13, 14, 15, 21, 22$). Một người phụ nữ mang chuyển đoạn cân bằng Robertson giữa NST 21 và chính NST 21 (tạo 1 NST kép $\\text{t}(21q;21q)$ và tổng bộ NST $2n = 45$) kết hôn với một người đàn ông bình thường ($2n = 46$). Khi loại trừ các hợp tử chết sớm (thể một 21), xác suất sinh con mắc hội chứng Down trong số các lần sinh con sống sót là bao nhiêu?","opts":["$33.33\\%$ ($\\frac{1}{3}$).","$100\\%$ (tất cả các con sinh ra sống sót đều mắc hội chứng Down).","$25\\%$.","$50\\%$."],"ans":1,"exp":"CỰC KỲ LƯU Ý BẪY HSG: Khác với chuyển đoạn $\\text{t}(14;21)$ cho $\\frac{1}{3}$ con sống mắc Down, người mang chuyển đoạn đồng nhất $\\text{t}(21q;21q)$ chỉ tạo đúng 2 loại trứng: trứng mang $\\text{t}(21q;21q)$ (khi kết hợp tinh trùng bình thường 21 tạo hợp tử Trisomy 21 $\\rightarrow$ Down) và trứng không mang 21 (kết hợp tinh trùng 21 tạo Monosomy 21 $\\rightarrow$ chết phôi $100\\%$). Vậy $100\\%$ trẻ sống sót đều mắc Down!"},{"id":"MCQ-CL-116","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chu kỳ tế bào & Ung thư (Rb/E2F)","q":"Trong cơ chế kiểm soát điểm giới hạn (Restriction point) ở pha $G_1$ của tế bào động vật có vú, protein ức chế khối u $\\text{Rb}$ (Retinoblastoma) điều hòa yếu tố phiên mã $\\text{E2F}$ (yếu tố kích hoạt các gen tổng hợp enzyme pha $S$) như thế nào?","opts":["Protein $\\text{Rb}$ luôn kích thích $\\text{E2F}$ phiên mã liên tục trong suốt pha $G_0$.","Sự phosphoryl hóa $\\text{Rb}$ làm $\\text{Rb}$ bám chặt hơn nữa vào $\\text{E2F}$ để dừng chu kỳ.","Ở trạng thái chưa phosphoryl hóa (đầu $G_1$), protein $\\text{Rb}$ gắn chặt và BẤT HOẠT $\\text{E2F}$; khi nhận tín hiệu tăng trưởng, phức hợp $\\text{Cyclin D - Cdk4/6}$ phosphoryl hóa $\\text{Rb}$ làm $\\text{Rb}$ giải phóng $\\text{E2F}$ tự do để phiên mã các gen bước vào pha $S$.","Protein $\\text{Rb}$ phá hủy hoàn toàn các phức hợp Cyclin D."],"ans":2,"exp":"Đột biến mất chức năng cả hai alen $Rb$ (hoặc protein E7 của virus HPV gắn tranh $\\text{Rb}$) làm giải phóng vĩnh viễn $\\text{E2F}$, đẩy tế bào đi vào pha $S$ không cần tín hiệu phân chia, gây ung thư võng mạc hoặc ung thư cổ tử cung."},{"id":"MCQ-CL-117","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chu kỳ tế bào & Điểm kiểm soát","q":"Hội chứng Li-Fraumeni là một rối loạn di truyền trội làm tăng nguy cơ mắc nhiều loại ung thư ngay từ khi còn trẻ (ung thư vú, não, xương, máu). Bệnh nhân mang sẵn 1 alen đột biến mất chức năng của gen ức chế khối u $TP53$ (mã hóa protein $p53$) trong tất cả mọi tế bào sinh dưỡng ngay từ khi sinh ra. Theo giả thuyết 'Hai cú đánh' (Two-hit hypothesis) của Alfred Knudson, tại sao bệnh lại di truyền theo kiểu TRỘI trong phả hệ gia đình dù ở cấp độ tế bào đơn lẻ đột biến $TP53$ mang tính LẶN?","opts":["Vì chỉ cần thêm $1$ đột biến xôma ngẫu nhiên ('cú đánh thứ hai') làm hỏng nốt alen $TP53$ lành còn lại ở bất kỳ $1$ tế bào nào trong hàng nghìn tỷ tế bào cơ thể là đã đủ khởi phát khối u (xác suất xuất hiện khối u trong đời gần như $100\\%$), trong khi người bình thường phải chịu 2 cú đánh độc lập trên cùng 1 tế bào.","Vì chỉ cần 1 bản sao $TP53$ đột biến là $100\\%$ mọi tế bào tự động biến thành ung thư ngay từ phôi.","Vì alen $TP53$ lành bị imprinting tắt hoàn toàn ở mọi mô.","Vì gen $TP53$ nằm trên nhiễm sắc thể Y."],"ans":0,"exp":"Mô hình Knudson giải thích hoàn hảo cả ung thư võng mạc (Rb) và Li-Fraumeni (p53): ở cấp độ tế bào thì mất 2 alen mới biểu hiện (lặn), nhưng ở cấp độ cơ thể thừa hưởng 1 alen hỏng sẵn nên xác suất tích lũy mất alen thứ 2 trong đời rất cao, tạo kiểu phả hệ di truyền trội."},{"id":"MCQ-CL-118","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Mất đoạn NST","q":"Ở cà chua, 5 gen lặn ($a, b, c, d, e$) nằm trên cùng một nhánh của NST số 2. Tiến hành lai các dòng mang đột biến mất đoạn đồng nhất (Dòng 1 đến Dòng 4) với cây đồng hợp lặn ($abcde/abcde$) thu được kết quả kiểu hình giả trội ở đời con như sau:<br>• Dòng mất đoạn 1: biểu hiện lặn $b$ và $e$.<br>• Dòng mất đoạn 2: biểu hiện lặn $a, b, d$.<br>• Dòng mất đoạn 3: biểu hiện lặn $a$ và $d$.<br>• Dòng mất đoạn 4: biểu hiện lặn $c$ và $d$.<br>Biết mỗi đột biến chỉ mất duy nhất một đoạn NST liên tục. Trật tự sắp xếp đúng của 5 gen này trên nhiễm sắc thể là:","opts":["$c - d - a - b - e$ (hoặc đảo ngược $e - b - a - d - c$).","$a - b - c - d - e$.","$c - a - d - b - e$.","$d - c - a - e - b$."],"ans":0,"exp":"Phân tích tập hợp mất liên tiếp: Dòng 1 mất $\\{b, e\\}$; Dòng 2 mất $\\{a, b, d\\} \\Rightarrow b$ nằm giữa $(a,d)$ và $e$! Dòng 3 mất $\\{a, d\\} \\Rightarrow a$ cạnh $b$ (vì Dòng 2 có $a,d,b$ còn Dòng 3 chỉ có $a,d \\Rightarrow$ thứ tự $d - a - b - e$). Dòng 4 mất $\\{c, d\\} \\Rightarrow c$ nằm kề $d$ ở đầu ngoài. Trật tự chính xác: $c - d - a - b - e$!"},{"id":"MCQ-CL-119","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thể Barr & Chẩn đoán giới tính","q":"Trong một tế bào sinh dưỡng bình thường ở người phụ nữ, quan sát nhân tế bào kỳ trung gian thấy có $1$ Thể Barr (NST X bất hoạt đóng xoắn dị nhiễm sắc). Tuy nhiên, một người có bộ NST $47, XXY$ lại vẫn phát triển các đặc điểm sinh dục nam nhưng có $1$ thể Barr, còn một người phụ nữ mắc hội chứng Không nhạy cảm Androgen (AIS - kiểu gen $46, XY$ nhưng hỏng gen thụ thể Testosterone trên NST X nên ngoại hình hoàn toàn là nữ) sẽ có bao nhiêu Thể Barr trong tế bào niêm mạc má?","opts":["$1$ thể Barr (vì ngoại hình là nữ).","$0$ thể Barr (vì hệ gen chỉ có $1$ nhiễm sắc thể X duy nhất).","$2$ thể Barr.","$3$ thể Barr."],"ans":1,"exp":"Quy tắc Lyon đếm Thể Barr phụ thuộc thuần túy vào TỔNG SỐ NST X trong nhân ($N_{\\text{Barr}} = \\text{Số X} - 1$), hoàn toàn không phụ thuộc ngoại hình hay hormone! Người AIS có bộ NST $XY$ (1 X) nên có $1 - 1 = 0$ thể Barr."},{"id":"MCQ-CL-120","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân bào & Thí nghiệm Dung hợp tế bào","q":"Trong thí nghiệm kinh điển của Rao và Johnson (1970) về điều hòa chu kỳ tế bào bằng dung hợp hai tế bào động vật đang ở các pha khác nhau để tạo tế bào lai hai nhân:<br>• Thí nghiệm 1: Dung hợp tế bào ở pha $M$ (đang nguyên phân) với tế bào ở pha $G_1$.<br>• Thí nghiệm 2: Dung hợp tế bào ở pha $S$ với tế bào ở pha $G_2$.<br>Kết quả quan sát hiện tượng xảy ra với hai nhân của mỗi thí nghiệm là:","opts":["Cả hai thí nghiệm đều làm hai nhân nổ tung.","Thí nghiệm 1: Nhân $G_1$ bị ép đi ngay vào phân bào sớm (Premature chromosome condensation - PCC) với các NST co xoắn ở trạng thái ĐƠN (1 chromatid); Thí nghiệm 2: Nhân $G_2$ KHÔNG nhân đôi DNA thêm lần nữa (vẫn giữ $4C$ chờ phân bào).","Thí nghiệm 1: Nhân $M$ dừng nguyên phân quay về pha $G_1$; Thí nghiệm 2: Nhân $G_2$ nhân đôi DNA tiếp lên $8C$.","Thí nghiệm 1: Nhân $G_1$ co xoắn thành NST KÉP gồm 2 chromatid."],"ans":1,"exp":"Tế bào chất pha $M$ chứa yếu tố MPF hoạt hóa ép nhân $G_1$ co xoắn NST sớm dù DNA chưa nhân đôi (nên thấy NST đơn 1 sợi!). Tế bào chất pha $S$ chứa yếu tố thúc đẩy $S$, nhưng nhân $G_2$ đã mất phức hợp tiền sao chép (cấp phép $G_1$) nên tuyệt đối không tái bản lại trong cùng 1 chu kỳ!"},{"id":"MCQ-CL-121","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Giảm phân & Rối loạn kép","q":"Xét một loài động vật ($XX / XY$). Ở ruồi giấm, alen $A$ (mắt đỏ) trội hoàn toàn so với $a$ (mắt trắng) nằm trên vùng không tương đồng của NST X. Tiến hành lai ruồi cái mắt trắng ($X^a X^a$) với ruồi đực mắt đỏ ($X^A Y$). Đời con $F_1$ thu được phần lớn đúng quy luật di truyền chéo (cái đỏ, đực trắng), nhưng xuất hiện một số ít cá thể ngoại lệ gồm ruồi ĐỰC MẮT ĐỎ ($X^A O$, bất thụ) và ruồi CÁI MẮT TRẮNG ($X^a X^a Y$, hữu thụ). Cơ chế rối loạn phân bào nào giải thích đồng thời được cả hai loại cá thể ngoại lệ này (Thí nghiệm Bridges)?","opts":["Do tinh trùng của ruồi bố bị đột biến mất gen $A$ thành $a$.","Do đột biến chuyển đoạn từ X sang NST thường ở bố.","Do cặp NST giới tính $XY$ của ruồi bố không phân ly ở Giảm phân I tạo tinh trùng $X^A Y$ và $O$.","Cặp nhiễm sắc thể $X^a X^a$ của ruồi MẸ không phân ly trong giảm phân tạo ra hai loại trứng bất thường là $X^a X^a$ và trứng $O$ (không có X); khi thụ tinh với tinh trùng bình thường của bố ($X^A$ và $Y$) tạo ra hợp tử $X^A O$ (đực mắt đỏ) và $X^a X^a Y$ (cái mắt trắng) — lưu ý ở ruồi giấm giới tính quyết định bởi tỉ lệ $X/A$ chứ không phải NST Y."],"ans":3,"exp":"Ở ruồi giấm, $XXY$ là cái ($X/A = 2/2 = 1.0$) và $XO$ là đực ($X/A = 1/2 = 0.5$, bất thụ vì thiếu gen khả sản trên Y). Trứng $X^a X^a$ gặp tinh trùng $Y$ cho cái mắt trắng $X^a X^a Y$; trứng $O$ gặp tinh trùng $X^A$ cho đực mắt đỏ $X^A O$!"},{"id":"MCQ-CL-122","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Giảm phân & Giao tử đực","q":"Một tế bào sinh tinh có kiểu gen $\\frac{AB}{ab} \\frac{DE}{de}$ (liên kết trên 2 cặp NST tương đồng khác nhau) bước vào giảm phân. Trong quá trình giảm phân của <strong>duy nhất 1 tế bào sinh tinh này</strong>, giả sử xảy ra trao đổi chéo giữa $A$ và $a$ ở $1$ điểm trên cặp 1, đồng thời xảy ra trao đổi chéo giữa $D$ và $d$ ở $1$ điểm trên cặp 2. Kết thúc giảm phân, 1 tế bào sinh tinh đó thực tế có thể tạo ra tối đa bao nhiêu loại tinh trùng?","opts":["$8$ loại tinh trùng.","$16$ loại tinh trùng.","$2$ loại tinh trùng.","Tối đa $4$ loại tinh trùng (với tỉ lệ $1:1:1:1$, dù cả hai cặp đều xảy ra trao đổi chéo)."],"ans":3,"exp":"ĐÂY LÀ BẪY KINH ĐIỂN HSG: Một tế bào sinh tinh giảm phân CHỈ TẠO TỔNG CỘNG 4 TINH TRÙNG! Vì chỉ có đúng 4 sản phẩm cuối cùng nên cho dù có bao nhiêu cặp NST xảy ra trao đổi chéo đi nữa, từ 1 tế bào sinh tinh duy nhất cũng KHÔNG BAO GIỜ tạo được quá $4$ loại tinh trùng!"},{"id":"MCQ-CL-123","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thể đa bội & Tứ bội 4n","q":"Ở một loài thực vật tứ bội ($4n$), gen $A$ (hoa đỏ) trội hoàn toàn so với $a$ (hoa trắng). Người ta lấy hạt phấn của một cây hoa đỏ tứ bội chưa biết kiểu gen thụ phấn cho cây hoa trắng tứ bội ($aaaa$), đời con $F_1$ thu được tỉ lệ kiểu hình $5$ cây hoa đỏ : $1$ cây hoa trắng. Nếu lấy cây hoa đỏ tứ bội ban đầu cho <strong>tự thụ phấn</strong>, tỉ lệ các cá thể hoa trắng ($aaaa$) thu được ở đời con sẽ là bao nhiêu?","opts":["$\\frac{1}{12}$.","$\\frac{1}{36}$.","$\\frac{1}{16}$.","$\\frac{1}{4}$."],"ans":1,"exp":"Lai phân tích với $aaaa$ ($100\\% aa$) cho $5$ đỏ : $1$ trắng $\\Rightarrow$ cây hoa đỏ tạo $\\frac{1}{6}$ giao tử lặn $aa$ $\\Rightarrow$ kiểu gen của cây hoa đỏ đó là $AAaa$. Khi $AAaa$ tự thụ phấn: $\\frac{1}{6}aa \\times \\frac{1}{6}aa = \\frac{1}{36}$ hoa trắng."},{"id":"MCQ-CL-124","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Lai thể đa bội & Bất tương hợp","q":"Xét cây tứ bội có kiểu gen $AAaa$ và cây tứ bội có kiểu gen $Aaaa$ (gen $A$ trội hoàn toàn so với $a$). Biết cây tứ bội giảm phân tạo giao tử $2n$, nhưng chỉ có các giao tử mang ít nhất $1$ alen trội ($AA$ hoặc $Aa$) mới có khả năng sống và thụ tinh được ở hạt phấn (hạt phấn $aa$ bị bất thụ/chết); ở noãn mọi giao tử $2n$ đều thụ tinh bình thường. Nếu thực hiện phép lai $P: \\text{♀ } Aaaa \\times \\text{♂ } AAaa$, tỉ lệ kiểu hình hoa trắng ($aaaa$) ở đời con là bao nhiêu?","opts":["$\\frac{1}{36}$.","$\\frac{1}{10}$.","$\\frac{1}{12}$.","$0\\%$ ($100\\%$ cây đời con mang kiểu hình trội)."],"ans":3,"exp":"Để tạo kiểu hình lặn $aaaa$ ở đời con, BẮT BUỘC cả bố và mẹ đều phải cho được giao tử $aa$. Nhưng đề cho hạt phấn $aa$ của bố $AAaa$ bị bất thụ hoàn toàn (chỉ còn $AA$ và $Aa$ tham gia thụ tinh), nên đời con chắc chắn $100\\%$ mang alen $A$ ($0\\%$ lặn)!"},{"id":"MCQ-CL-125","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chu kỳ tế bào & Nấm men","q":"Leland Hartwell phát hiện các đột biến <i>cdc</i> (Cell Division Cycle) nhạy nhiệt độ ở nấm men nảy chồi <i>Saccharomyces cerevisiae</i> để tìm hiểu các gen điều hòa chu kỳ tế bào. Nếu một chủng nấm men mang đột biến mất chức năng ở gen $cdc28$ (mã hóa CDK duy nhất ở nấm men - tương đương $Cdk1$) bị chuyển lên nhiệt độ hạn chế ($37^\\circ\\text{C}$), quần thể tế bào nấm men sẽ dừng kẹt đồng loạt ở dạng hình thái nào?","opts":["Tế bào phân chia nhanh bất tử tạo hàng tỷ chồi nhỏ xíu.","Tế bào chuyển sang sinh sản hữu tính tạo 8 bào tử.","Nhân đôi DNA 10 lần liên tiếp không phân chia tế bào chất.","Các tế bào dừng kẹt lại ở pha $G_1$ (không nảy chồi được, kích thước phồng to) hoặc dừng trước pha $M$ tùy pha nhạy cảm của allele, không thể đi vào sao chép DNA hay phân chia nhân."],"ans":3,"exp":"Cdk1 (Cdc28 ở <i>S. cerevisiae</i>, Cdc2 ở <i>S. pombe</i>) là kinase điều hòa trung tâm không thể thiếu tại cả điểm START ($G_1/S$) và $G_2/M$; mất chức năng kinase khiến tế bào đóng băng chu kỳ ở trạng thái hình thái đồng nhất."},{"id":"MCQ-CL-126","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân bào & Cohesin/Condensin","q":"Phân biệt vai trò cấu trúc của hai phức hợp protein thuộc họ SMC trên nhiễm sắc thể trong phân bào nhân thực là <strong>Cohesin</strong> và <strong>Condensin</strong>:","opts":["Cả hai đều có chức năng tháo xoắn DNA tại chạc chữ Y trong pha S.","Cohesin chỉ có ở vi khuẩn còn Condensin chỉ có ở virus.","Condensin nối hai nhiễm sắc tử chị em lại với nhau còn Cohesin cắt đứt tâm động.","Cohesin giữ hai nhiễm sắc tử chị em dính chặt với nhau từ khi nhân đôi ở pha $S$ cho đến kỳ sau (giúp nhận diện cặp chị em trên thoi phân bào); Condensin hoạt động mạnh từ kỳ đầu giúp cuộn xoắn nén chặt sợi nhiễm sắc thành NST dạng que gọn gàng."],"ans":3,"exp":"Cohesin tạo vòng kẹp giữ 2 chị em sau sao chép (chờ Separase cắt ở kỳ sau); Condensin tạo vòng lặp nén chặt chất nhiễm sắc trong pha $M$ để NST không bị rối đứt khi kéo về 2 cực."},{"id":"MCQ-CL-127","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Lệch bội & Rối loạn Phân bào","q":"Ở một loài động vật lưỡng bội ($2n = 14$), tại vùng sinh sản của tuyến sinh dục đực có $20$ tế bào sinh dục sơ khai nguyên phân liên tiếp $3$ đợt tạo ra các tế bào sinh tinh. Tất cả các tế bào sinh tinh đều đi vào giảm phân bình thường, NGOẠI TRỪ có $10$ tế bào sinh tinh bị rối loạn không phân ly cặp NST số 1 ở Giảm phân I (cặp số 1 ở GP II và mọi cặp khác đều bình thường). Tính tỉ lệ phần trăm tinh trùng mang đúng $7$ NST (bình thường) trên tổng số tinh trùng tạo thành:","opts":["$90.00\\%$.","$87.50\\%$.","$93.75\\%$.","$96.875\\%$."],"ans":2,"exp":"Tổng số tế bào sinh tinh $= 20 \\times 2^3 = 160$ tế bào. Trong đó có $10$ tế bào rối loạn GP I tạo $100\\%$ tinh trùng bất thường ($n+1$ hoặc $n-1$), $150$ tế bào bình thường tạo $100\\%$ tinh trùng bình thường ($n=7$). Vậy tỉ lệ tinh trùng bình thường $= \\frac{150}{160} = 0.9375 = 93.75\\%$."},{"id":"MCQ-CL-128","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chẩn đoán di truyền & Thể khảm","q":"Xét nghiệm mẫu máu ngoại vi của một bé gái có kiểu hình hội chứng Turner nhẹ cho thấy $60\\%$ tế bào bạch cầu lympho mang bộ NST $45, X$ ($XO$) và $40\\%$ tế bào mang bộ NST $46, XX$ (hội chứng Turner thể khảm). Cơ chế phát sinh nào giải thích hợp lý nhất cho trường hợp thể khảm $45, X / 46, XX$ này?","opts":["Hợp tử ban đầu có bộ NST bình thường $46, XX$, nhưng trong một lần nguyên phân sớm của phôi (ví dụ ở giai đoạn phôi vài tế bào) đã xảy ra sự không phân ly hoặc thất lạc (anaphase lag) một chiếc NST X ở một phôi bào, tạo dòng tế bào $45, X$ phát triển song song với dòng $46, XX$.","Do mẹ bị đột biến $XO$ và bố bị đột biến $XXY$.","Do hiện tượng trao đổi chéo giữa NST 21 và NST X trong giảm phân.","Do một tinh trùng $X$ và một tinh trùng $O$ cùng thụ tinh vào 1 trứng."],"ans":0,"exp":"Thể khảm (Mosaicism) chỉ có hai dòng tế bào $45, X / 46, XX$ phát sinh từ hợp tử lưỡng bội bình thường $46, XX$ bị thất lạc 1 NST X (mất 1 chromatid X trong kỳ sau nguyên phân phôi sớm, tạo $45,X$ và $46,XX$ — nếu không phân ly tạo $45,X / 47,XXX$, còn thất lạc anaphase lag tạo đúng $45,X / 46,XX$!)."},{"id":"MCQ-CL-129","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bất thường Hợp tử & Thể đa bội","q":"Ở người, hiện tượng trứng được thụ tinh cùng lúc bởi HAI tinh trùng (Dispermy) tạo hợp tử tam bội ($3n = 69$). Kết quả phát triển của thai kỳ chứa hợp tử $69, XXY$ hoặc $69, XXX$ (tam bội) thường dẫn tới kết cục nào?","opts":["Thường gây sảy thai tự nhiên rất sớm hoặc thai trứng bán phần (Partial hydatidiform mole), hầu như không có khả năng sống sót sau sinh.","Phát triển thành người trưởng thành cao lớn khỏe mạnh như cây trồng tam bội.","Tự động loại bỏ 23 NST thừa để trở thành người khỏe mạnh bình thường.","Chỉ gây bệnh mù màu nhẹ."],"ans":0,"exp":"Đa bội ở người ($3n = 69$) cực kỳ độc hại cho phát triển phôi thai và mất cân bằng in dấu hệ gen (2 bộ bố + 1 bộ mẹ tạo thai trứng bán phần), gây chết thai sớm."},{"id":"MCQ-CL-130","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân bào & Thoi vô sắc","q":"Trong kỳ sau của nguyên phân, lực kéo hai nhóm nhiễm sắc thể đơn về hai cực đối diện được thực hiện đồng thời bởi hai cơ chế phối hợp là Anaphase A và Anaphase B. Sự khác biệt giữa Anaphase A và Anaphase B là gì?","opts":["Anaphase A diễn ra ở động vật; Anaphase B chỉ có ở vi khuẩn.","Anaphase A là tách tế bào chất; Anaphase B là tái lập màng nhân.","Anaphase A kéo dài các vi ống thể động làm NST dồn vào giữa.","Anaphase A là sự rút ngắn của các vi ống thể động (kéo NST tiến về cực); Anaphase B là sự trượt dài ra xa nhau của các vi ống cực (từ hai cực ngược chiều trượt lên nhau nhờ Kinesin-5) và lực kéo của vi ống sao ra vỏ tế bào, đẩy hai cực tế bào tách xa nhau."],"ans":3,"exp":"Anaphase A rút ngắn khoảng cách NST - cực (giải trùng hợp vi ống thể động tại thể động/cực), còn Anaphase B nới rộng khoảng cách giữa hai cực thoi phân bào."},{"id":"MCQ-CL-131","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đột biến Lệch bội & Dạng thể","q":"Một loài thực vật có bộ NST lưỡng bội $2n = 20$. Số lượng nhiễm sắc thể trong một tế bào sinh dưỡng của Thể bốn ($2n+2$), Thể ba kép ($2n+1+1$) và Thể không ($2n-2$) lần lượt là bao nhiêu, và số dạng thể bốn tối đa khác nhau về NST bị thừa có thể có của loài là bao nhiêu?","opts":["$22$; $21$; $18$ NST và có tối đa $20$ dạng thể bốn.","$22$; $22$; $19$ NST và có tối đa $45$ dạng thể bốn.","$22$; $22$; $18$ NST và có tối đa $10$ dạng thể bốn.","$40$; $22$; $10$ NST và có tối đa $45$ dạng thể bốn."],"ans":2,"exp":"$2n=20 \\Rightarrow n=10$ cặp. Thể bốn ($2n+2=22$), thể ba kép ($2n+1+1=22$), thể không ($2n-2=18$). Thể bốn chỉ thừa 2 chiếc ở cùng 1 cặp NST $\\Rightarrow C^1_{10} = 10$ dạng (khác thể ba kép có $C^2_{10} = 45$ dạng)."},{"id":"MCQ-CL-132","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chu kỳ tế bào & Trung thể","q":"Trong tế bào động vật, trung thể (Centrosome, gồm cặp trung tử trực giao) đóng vai trò trung tâm tổ chức vi ống (MTOC). Điều gì xảy ra nếu một tế bào bình thường nhân đôi trung thể SAI LỆCH tạo ra $3$ hoặc $4$ trung thể ở đầu pha M (thường gặp trong tế bào ung thư)?","opts":["Tạo ra 4 tế bào con có bộ NST $2n$ hoàn toàn chuẩn xác.","Hình thành thoi phân bào đa cực (3 hoặc 4 cực), kéo phân chia hỗn loạn các nhiễm sắc thể vào các tế bào con dẫn đến lệch bội nghiêm trọng và bất ổn định bộ gen (Aneuploidy).","Các NST tự động biến mất.","Tế bào không thể sao chép DNA ở pha S."],"ans":1,"exp":"Khuếch đại trung thể (Centrosome amplification) tạo thoi phân bào đa cực gây phân ly sai nhiễm sắc thể nghiêm trọng, là động lực tiến hóa nhanh của khối u ác tính."},{"id":"MCQ-CL-133","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Giảm phân & Cặp NST X-Y","q":"Ở động vật có vú (như người, chuột), hai nhiễm sắc thể giới tính X và Y có hình dạng và phần lớn trình tự gen hoàn toàn khác nhau, nhưng trong giảm phân ở cá thể đực ($XY$), chúng vẫn bắt cặp và phân ly chính xác về 2 cực ở Giảm phân I. Cấu trúc nào trên X và Y cho phép chúng tiếp hợp và tạo trao đổi chéo bắt buộc ở kỳ đầu I?","opts":["Vùng tâm động của NST số 21.","Thể Barr đóng xoắn ở đầu NST X.","Vùng tương đồng giả NST thường (Pseudoautosomal regions - PAR1 và PAR2) nằm ở hai đầu mút của cả NST X và NST Y.","Vùng gen $SRY$ nằm trên vai ngắn NST Y."],"ans":2,"exp":"Các đoạn PAR ở hai đầu mút X và Y có trình tự tương đồng nhau, cho phép X và Y bắt cặp và thực hiện tối thiểu 1 sự kiện trao đổi chéo bắt buộc ở kỳ đầu I để kéo phân ly đúng về 2 cực."},{"id":"MCQ-CL-134","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Tế bào & Cá thể $3n/4n$","q":"Một loài thực vật lưỡng bội có $2n = 12$. Trong tế bào sinh dưỡng của một cây người ta đếm được $24$ nhiễm sắc thể. Làm thế nào chỉ bằng việc quan sát cặp tương đồng hoặc phép lai phân tích kiểm tra để phân biệt chắc chắn cây $24$ NST này là <strong>Thể tự tứ bội</strong> ($4n$ của cùng loài) hay <strong>Thể song nhị bội</strong> ($2n_A + 2n_B$ từ 2 loài có $2n=12$)?","opts":["Thể tự tứ bội không thể thực hiện nguyên phân.","Thể tự tứ bội có 12 NST còn Thể song nhị bội có 24 NST.","Ở Thể tự tứ bội ($4n$), khi giảm phân kỳ đầu I có thể thấy hình thành các <strong>tứ trị</strong> (4 NST giống nhau bắt cặp) và khi lai kiểu gen $AAAA \\times aaaa \\rightarrow AAaa$ tự thụ cho phân ly kiểu hình đặc trưng $35:1$ (từ $AAaa$); còn ở Thể song nhị bội, các NST chỉ bắt cặp thành <strong>12 lưỡng trị</strong> riêng rẽ giống lưỡng bội và lai phân ly theo kiểu gen $AA \\times aa$ hay hai gen độc lập.","Thể song nhị bội hoàn toàn bất thụ không có hạt."],"ans":2,"exp":"Sự khác biệt kinh điển: Tự đa bội (Autotetraploid) có 4 bộ tương đồng (hình thành quadrivalent, di truyền kiểu tứ bội $35:1$); Dị đa bội (Allotetraploid) có 2 cặp bộ lưỡng bội khác nguồn (chỉ tạo bivalent, di truyền kiểu lưỡng bội phân ly đôi một)."},{"id":"MCQ-CL-135","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Công nghệ Tế bào & Chuyển nhân","q":"Mặc dù nhân bản vô tính cừu Dolly chứng minh nhân của tế bào soma trưởng thành đã biệt hóa vẫn giữ nguyên toàn bộ bộ gen để tái lập trình thành cơ thể hoàn chỉnh, nhưng hiệu suất thành công của kỹ thuật chuyển nhân tế bào soma (SCNT) thường cực kỳ thấp (chỉ khoảng $1-3\\%$). Nguyên nhân sinh học chính là gì?","opts":["Cừu không có khả năng sinh sản hữu tính.","Tế bào tuyến vú trưởng thành đã bị mất mất một nửa số nhiễm sắc thể.","Tế bào chất của trứng không có ty thể cung cấp ATP.","Các dấu ấn biểu sinh (Methyl hóa DNA, sửa đổi Histone chuyên biệt của tế bào tuyến vú trưởng thành) không được tế bào chất trứng tái lập trình xóa sạch và đặt lại về trạng thái phôi toàn năng một cách hoàn hảo, dẫn đến rối loạn biểu hiện gen phôi sớm."],"ans":3,"exp":"DNA của tế bào biệt hóa vẫn nguyên vẹn về mặt trình tự, nhưng mang 'bộ nhớ biểu sinh' (Epigenetic marks) rất bền vững; việc tái lập trình biểu sinh không hoàn chỉnh gây lệch biểu hiện các gen phát triển phôi (như <i>Oct4, Nanog</i>)."},{"id":"MCQ-CL-136","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đột biến Cấu trúc & Chữ thập","q":"Ở người bình thường mang đột biến chuyển đoạn tương hỗ cân bằng giữa NST số 4 và NST số 10 ($4, 4^t, 10, 10^t$), trong kỳ đầu Giảm phân I, bốn NST này tiếp hợp tạo hình chữ thập. Nếu xảy ra kiểu phân ly <strong>Liền kề 1 (Adjacent-1)</strong> (NST không tương đồng tâm động đi cùng nhau: $4 + 10^t$ về một cực, $4^t + 10$ về cực kia), các giao tử tạo thành có đặc điểm gì?","opts":["Một cực nhận 3 NST và cực kia nhận 1 NST.","Chỉ tạo ra các giao tử chết trước khi bước vào giảm phân II.","Cả hai loại giao tử đều mất cân bằng di truyền (vừa mang thừa/lặp đoạn của một NST, vừa bị thiếu/mất đoạn của NST kia) nên thường gây bất thụ hoặc hợp tử dị tật nặng.","Cả hai loại giao tử đều hoàn toàn cân bằng gen và bình thường $100\\%$."],"ans":2,"exp":"Trong 3 kiểu phân ly 2-2 của phức hợp chữ thập: chỉ có Alternate ($4+10$ và $4^t+10^t$) cho giao tử cân bằng; cả Adjacent-1 (tâm động khác loại) và Adjacent-2 (tâm động cùng loại đi chung cực) đều tạo giao tử lặp-mất đoạn."},{"id":"MCQ-CL-137","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân bào & Kiểm tra DNA","q":"Nếu bổ sung chất Hydroxyurea (chất ức chế enzyme Ribonucleotide reductase, làm cạn kiệt nguồn dNTP dùng cho sao chép DNA) vào tế bào động vật đang ở pha $S$, hệ thống giám sát điểm kiểm soát nội pha $S$ (Intra-S checkpoint - qua đường dẫn $\\text{ATR - Chk1}$) sẽ đáp ứng như thế nào để bảo vệ chạc ba nhân đôi?","opts":["Ép tế bào bước ngay vào kỳ sau nguyên phân để xé đôi DNA đang sao chép dở.","Tạm dừng phát khởi các đơn vị tái bản (Ori) muộn chưa kích hoạt, ổn định các chạc ba đang bị kẹt để tránh đứt gãy sợi kép và ngăn không cho tế bào bước vào pha $M$ (ức chế Cdc25 $\\rightarrow$ bất hoạt Cdk1).","Hoạt hóa enzyme Caspase-3 giết chết tế bào ngay lập tức sau 1 giây.","Đẩy nhanh tốc độ sao chép lên gấp 10 lần dù thiếu dNTP."],"ans":1,"exp":"Khi chạc ba sao chép bị đình trệ lộ ra các đoạn DNA mạch đơn bọc bởi RPA, phức hợp cảm biến $\\text{ATR/ATRIP}$ kích hoạt kinase $\\text{Chk1}$ làm phanh hãm chu kỳ, bảo vệ chạc ba và chờ nguồn dNTP phục hồi."},{"id":"MCQ-CL-138","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hội chứng Lệch bội & Bất hoạt X","q":"Tại sao những người mang đột biến lệch bội ở nhiễm sắc thể giới tính như Siêu nữ ($47, XXX$), Klinefelter ($47, XXY$) hay thậm chí $48, XXXX$ vẫn có thể sống sót khỏe mạnh tương đối bình thường đến tuổi trưởng thành, trong khi thể ba ở hầu hết các NST thường lớn (như Trisomy 1, 2, 3...) lại gây chết phôi $100\\%$?","opts":["Vì nhiễm sắc thể X không mang bất kỳ gen thiết yếu nào.","Vì các NST X dư thừa tự động bị đào thải ra ngoài tế bào sau khi sinh.","Vì nam giới và nữ giới không cần sử dụng các gen trên NST X.","Do cơ chế Bất hoạt NST X (tạo thể Barr) giúp vô hiệu hóa hầu hết các gen trên tất cả các NST X dư thừa (chỉ giữ lại 1 NST X hoạt động trong mỗi tế bào), nhờ đó cân bằng liều lượng gen gần như bình thường; trong khi không có cơ chế tương tự cho NST thường (trừ các NST rất nhỏ ít gen như 21, 18, 13 mới sống được tới lúc sinh)."],"ans":3,"exp":"Bất hoạt X (Lyonization) đóng vai trò bộ đệm liều lượng gen cực hiệu quả cho NST X (chỉ còn một phần nhỏ gen thoát bất hoạt ở vùng PAR gây biểu hiện nhẹ như chiều cao tăng hoặc giảm khả năng sinh sản)."},{"id":"MCQ-CL-139","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh học Tế bào Gốc","q":"So sánh tiềm năng biệt hóa giữa Tế bào gốc phôi (Embryonic stem cells - ESC lấy từ khối tế bào bên trong ICM của phôi nang) và Tế bào gốc trưởng thành tủy xương tạo máu (Hematopoietic stem cells - HSC), phát biểu nào là chính xác?","opts":["ESC có tính <strong>vạn năng</strong> (Pluripotent - biệt hóa được thành tất cả mọi loại tế bào của 3 lá phôi trừ mô nhau thai), còn HSC có tính <strong>đa tiềm năng</strong> (Multipotent - chỉ biệt hóa thành các dòng tế bào máu và miễn dịch).","Tế bào gốc trưởng thành hoàn toàn không thể tự làm mới (self-renewal).","HSC có tính toàn năng tạo được nguyên một phôi thai mới.","ESC chỉ biệt hóa được thành duy nhất tế bào hồng cầu."],"ans":0,"exp":"Thứ bậc tiềm năng tế bào gốc: Toàn năng (Totipotent: hợp tử/phôi 2-8 TB) $>$ Vạn năng (Pluripotent: ESC, iPSC) $>$ Đa tiềm năng (Multipotent: tế bào gốc tạo máu, thần kinh) $>$ Đơn tiềm năng (Unipotent)."},{"id":"MCQ-CL-140","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tế bào gốc cảm ứng iPSC","q":"Trong công trình đoạt giải Nobel Y học của Shinya Yamanaka, việc đưa $4$ yếu tố phiên mã ($Oct4, Sox2, Klf4, c-Myc$) vào tế bào nguyên bào sợi da trưởng thành đã tạo ra Tế bào gốc vạn năng cảm ứng (iPSC). Ý nghĩa mang tính cách mạng nhất của công nghệ iPSC trong y học tái tạo là gì?","opts":["Làm cho tế bào hồng cầu nhân đôi không cần DNA.","Tạo ra nguồn tế bào gốc vạn năng mang CHÍNH hệ gen của bệnh nhân (từ tế bào da/máu trưởng thành) để biệt hóa thành mô thay thế ghép lại cho bệnh nhân mà KHÔNG bị thải ghép miễn dịch và KHÔNG vướng tranh cãi đạo đức phá hủy phôi người.","Biến đổi tế bào người thành tế bào thực vật có khả năng quang hợp.","Thay thế hoàn toàn quá trình thụ tinh tự nhiên bằng sinh sản vô tính ở người."],"ans":1,"exp":"iPSC lập trình ngược (reprogramming) đồng hồ biểu sinh của tế bào soma trưởng thành quay về trạng thái vạn năng giống ESC, mở ra y học cá thể hóa và mô hình hóa bệnh di truyền trên đĩa nuôi cấy."},{"id":"MCQ-CL-141","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân bào & Rối loạn Hợp tử","q":"Ở một loài thực vật giao phấn có $2n = 14$. Xét một cặp cây bố mẹ đều có kiểu gen $Aa$ (gen nằm trên cặp NST số 1). Khi cây mẹ giảm phân tạo noãn, toàn bộ các cặp NST khác phân ly bình thường, riêng ở cặp NST số 1 có $20\\%$ số tế bào không phân ly ở Giảm phân II. Cây bố giảm phân bình thường. Ở đời con thu được, tỉ lệ hợp tử mang kiểu gen $AAa$ chiếm bao nhiêu phần trăm? (Giả sử mọi giao tử đều thụ tinh và hợp tử đều sống sót; trường hợp rối loạn GP II chỉ xảy ra ở 1 trong 2 tế bào con hoặc tính chung tỉ lệ đều như nhau đối với hợp tử $AAa$ nếu biết trong $20\\%$ tế bào rối loạn GP II có một nửa tạo giao tử $AA$ còn lại là $aa$? Khoan: trong 1 tế bào sinh noãn bất kỳ, chỉ có 1 tế bào con đi tiếp GP II hoặc tạo trứng $AA$ hay $aa$ với xác suất đều $50\\%$!)","opts":["$2.5\\%$.","$10.0\\%$.","$1.25\\%$.","$5.0\\%$."],"ans":0,"exp":"Tế bào mẹ $Aa$ giảm phân I bình thường tách thành hai tế bào (một tế bào chứa $AA$, một chứa $aa$ với xác suất ngang nhau $\\frac{1}{2}$). Nếu rối loạn GP II ở $20\\%$ số tế bào sinh trứng (chỉ $1$ trong $2$ cực bị kẹt hoặc xác suất rơi vào dòng trứng của tế bào $AA$ là $\\frac{1}{2}$ và sau GP II tạo trứng $AA$ chiếm $\\frac{1}{2}$ trong dòng đó $\\Rightarrow$ xác suất tạo trứng $AA = 20\\% \\times \\frac{1}{2} \\times \\frac{1}{2} = 5\\%$). Kết hợp với tinh trùng $a$ ($50\\%$) của bố cho tỉ lệ $AAa = 5\\% \\times 0.5 = 2.5\\%$."},{"id":"MCQ-CL-142","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Mất đoạn & Lệch bội","q":"Người ta phát hiện một cá thể ruồi giấm cái có kiểu hình bình thường nhưng khi lai với ruồi đực bình thường, ở đời con thấy có $1/3$ cá thể cái và $1/3$ cá thể đực sống sót, đồng thời $50\\%$ số trứng do ruồi cái mẹ đẻ ra chết ở giai đoạn phôi (tỉ lệ con cái : con đực trưởng thành là $2$ cái : $1$ đực). Biết ruồi đực bố hoàn toàn bình thường. Bất thường di truyền nào ở ruồi cái mẹ giải thích tốt nhất hiện tượng chết phôi đực một nửa ($2$ cái : $1$ đực)?","opts":["Ruồi cái mẹ mang bộ NST $XXX$.","Ruồi cái mẹ dị hợp tử mang một đột biến GÂY CHẾT LẶN liên kết trên NST X ($X^A X^a$, với $a$ là alen gây chết ở trạng thái bán hợp tử $X^a Y$): đời con gồm $X^A X^A$ (sống), $X^A X^a$ (sống), $X^A Y$ (sống) và $X^a Y$ (chết phôi!), tạo tỉ lệ sống $2$ cái : $1$ đực.","Ruồi cái mẹ bị mất đoạn trên cả hai NST số 2.","Ruồi đực bố mang đột biến gây chết trên NST Y."],"ans":1,"exp":"Thí nghiệm cổ điển kiểm tra đột biến gây chết lặn trên X (phát hiện của Morgan và Muller): mẹ mang dị hợp $X^+ X^l$ lai với bố bình thường $X^+ Y$ cho $2$ con cái sống ($X^+ X^+, X^+ X^l$), $1$ con đực sống ($X^+ Y$) và $1$ con đực chết ($X^l Y$)."},{"id":"MCQ-CL-143","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chu kỳ tế bào & Nguyên phân","q":"Ở một loài thực vật có $2n = 16$, khi quan sát một tiêu bản rễ hành đang nguyên phân người ta bắt gặp một tế bào mà ở kỳ sau có $34$ nhiễm sắc thể đơn đang phân ly về hai cực ($17$ NST đơn về một cực và $17$ NST đơn về cực kia). Kết luận chắc chắn nhất về nguồn gốc bất thường của tế bào này là gì?","opts":["Tế bào rễ hành này vốn dĩ là tế bào của một cây <strong>Thể ba ($2n + 1 = 17$)</strong> ngay từ trước khi bước vào nguyên phân (nên ở kỳ sau nguyên phân nhân đôi tách tâm động thành $34$ NST đơn chia đều $17-17$).","Đây là tế bào thể bốn ($2n + 2 = 18$).","Đây là tế bào đang ở kỳ sau Giảm phân I.","Đây là tế bào bình thường $2n = 16$ bị rối loạn không phân ly ở chính kỳ sau này."],"ans":0,"exp":"Nếu một tế bào $2n = 16$ bị không phân ly trong nguyên phân ở kỳ sau thì tổng số NST đơn của tế bào vẫn chỉ bằng $32$ (chia lệch $17$ và $15$, hoặc $18$ và $14$), không thể tự dưng sinh ra $34$ NST đơn chia đều $17-17$ trừ phi bộ NST ban đầu ở $G_1$ đã là $17$!"},{"id":"MCQ-CL-144","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cấu trúc NST & Tâm động","q":"Các nhiễm sắc thể ở sinh vật nhân thực bình thường chỉ có duy nhất MỘT tâm động (Monocentric). Trong một sự kiện đứt gãy và nối sai sau chiếu xạ tia X, nếu một nhiễm sắc thể tái tổ hợp mang HAI tâm động nằm cách xa nhau (Dicentric chromosome) đi vào nguyên phân, điều gì thường xảy ra ở Kỳ sau?","opts":["Hai tâm động trên cùng một nhiễm sắc tử có xác suất cao ($50\\%$) bị gắn vào thoi phân bào từ HAI CỰC ĐỐI DIỆN, bị kéo căng thành 'cầu nhiễm sắc' (anaphase bridge) ở kỳ sau và đứt gãy ngẫu nhiên (chu trình Đứt - Nối - Cầu của Barbara McClintock).","Thoi phân bào biến mất hoàn toàn không kéo được bất kỳ NST nào.","Nhiễm sắc thể đó luôn di chuyển nguyên vẹn về 1 cực.","Nhiễm sắc thể hai tâm động nhân đôi nhanh gấp đôi bình thường."],"ans":0,"exp":"Chu trình Breakage-Fusion-Bridge (BFB) do Barbara McClintock phát hiện ở ngô xảy ra khi NST 2 tâm động bị xé đứt ở kỳ sau, tạo các đầu gãy dính lại sau sao chép, làm đảo lộn mạnh mẽ cấu trúc bộ gen trong ung thư."},{"id":"MCQ-CL-145","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân bào & Giao tử $4n$","q":"Trong phép lai giữa hai cây tứ bội có kiểu gen chưa biết cùng có kiểu hình hoa đỏ (biết $A$ trội hoàn toàn so với $a$, các cây $4n$ chỉ tạo giao tử $2n$ hữu thụ). Đời con $F_1$ thu được tỉ lệ phân ly kiểu hình là $3$ cây hoa đỏ : $1$ cây hoa trắng. Kiểu gen của cặp bố mẹ $P$ chắc chắn phải là:","opts":["$Aaaa \\times Aaaa$.","$AAAa \\times Aaaa$.","$AAaa \\times AAaa$.","$AAaa \\times Aaaa$."],"ans":0,"exp":"$Aaaa$ tạo $(\\frac{1}{2}Aa : \\frac{1}{2}aa)$. Khi $Aaaa \\times Aaaa$: hoa trắng $aaaa = \\frac{1}{2} \\times \\frac{1}{2} = \\frac{1}{4} \\Rightarrow$ Tỉ lệ $3$ đỏ : $1$ trắng! ($AAaa \\times Aaaa$ cho $11:1$; $AAaa \\times AAaa$ cho $35:1$; $AAAa \\times Aaaa$ cho $100\\%$ đỏ)."},{"id":"MCQ-CL-146","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Tế bào & Chuối $3n$","q":"Tại sao một số loài cây ăn quả tam bội ($3n$) như chuối trồng (<i>Musa acuminata</i> AAA) không có hạt, bất thụ hữu tính hoàn toàn nhưng vẫn tồn tại và được con người nhân giống phổ biến qua hàng nghìn năm?","opts":["Vì chuối tam bội $3n$ vẫn giảm phân tạo $100\\%$ hạt phấn và noãn bình thường.","Nhờ hình thức sinh sản sinh dưỡng tự nhiên bằng chồi nách / thân ngầm (chồi chuối con) kết hợp phương pháp nuôi cấy mô tế bào, giữ nguyên vẹn kiểu gen ưu việt qua nguyên phân.","Vì chuối tam bội thụ tinh chéo với cây cam.","Vì mỗi quả chuối thực chất là một bào tử nấm."],"ans":1,"exp":"Chuối nhà tam bội ($3n = 33$) cho quả to, ngọt và không hạt cứng; nhược điểm bất thụ hữu tính được khắc phục bằng sinh sản vô tính (tách chồi hoặc vi nhân giống in vitro)."},{"id":"MCQ-CL-147","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chu kỳ tế bào & Phóng xạ","q":"Sử dụng máy đếm tế bào dòng chảy (Flow cytometry) nhuộm DNA bằng chất huỳnh quang Propidium iodide để đo phân bố hàm lượng DNA trên $10.000$ tế bào nuôi cấy đang phân chia bình thường. Biểu đồ thu được có hai đỉnh chính tại giá trị huỳnh quang $200$ đơn vị (ứng với $2C$) và $400$ đơn vị (ứng với $4C$), nối với nhau bằng một vùng bằng ở giữa ($200 - 400$). Nếu bổ sung thuốc Nocodazole (khóa vi ống, chặn tế bào ở Kỳ giữa nguyên phân) trong $12\\text{ giờ}$ trước khi đo, hình dạng biểu đồ Flow cytometry sẽ biến đổi như thế nào?","opts":["Đỉnh tại vị trí $200$ ($2C$) giảm mạnh về gần $0$, trong khi đỉnh tại vị trí $400$ ($4C$) tăng vọt lên chiếm áp đảo hầu hết quần thể tế bào.","Xuất hiện đỉnh mới ở vị trí $100$ ($1C$).","Đỉnh $200$ ($2C$) tăng lên $100\\%$ và đỉnh $400$ biến mất.","Biểu đồ hoàn toàn không thay đổi."],"ans":0,"exp":"Trong biểu đồ chu kỳ tế bào, đỉnh $2C$ là pha $G_1$, vùng giữa $2C\\rightarrow 4C$ là pha $S$, và đỉnh $4C$ gồm pha $G_2 + M$. Nocodazole kẹt toàn bộ tế bào tại kỳ giữa $M$ (đã nhân đôi DNA xong nên ở mức $4C$), làm dồn tất cả tế bào về đỉnh $4C$!"},{"id":"MCQ-CL-148","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đột biến Lệch bội & Giao tử","q":"Ở cà độc dược ($2n = 24$), một cây thể ba ở cặp NST số 1 mang kiểu gen $AAa$. Khi cho cây $AAa$ này giao phấn với cây $AAa$ khác, biết hạt phấn $n+1$ hoàn toàn KHÔNG thụ tinh được (chỉ hạt phấn $n$ thụ tinh), còn noãn $n$ và $n+1$ thụ tinh bình thường. Tỉ lệ cây con có bộ NST <strong>thể ba</strong> ($2n+1$) và tỉ lệ cây con <strong>thể lưỡng bội</strong> ($2n$) ở đời $F_1$ lần lượt là:","opts":["$33.33\\%$ thể ba và $66.67\\%$ thể lưỡng bội.","$50\\%$ thể ba ($2n+1$) và $50\\%$ thể lưỡng bội ($2n$).","$100\\%$ thể ba ($2n+1$).","$25\\%$ thể ba ($2n+1$) và $75\\%$ thể lưỡng bội ($2n$)."],"ans":1,"exp":"Ở cây thể ba ($2n+1$) khi giảm phân bình thường luôn tạo ra $50\\%$ noãn $n$ và $50\\%$ noãn $n+1$ (cộng $AAa$: $\\frac{1}{6}AA + \\frac{2}{6}Aa = \\frac{1}{2}$ noãn $n+1$, và $\\frac{2}{6}A + \\frac{1}{6}a = \\frac{1}{2}$ noãn $n$). Bố chỉ truyền hạt phấn $n$ ($100\\% n$). Vậy $50\\%$ noãn $(n+1) \\times n \\rightarrow 50\\%$ thể ba $(2n+1)$, và $50\\%$ noãn $n \\times n \\rightarrow 50\\%$ thể lưỡng bội $(2n)$!"},{"id":"MCQ-CL-149","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đột biến Cà độc dược","q":"Ở một loài thực vật ($2n = 14$), gen $A$ (hoa đỏ) trội hoàn toàn so với $a$ (hoa trắng). Người ta cho cây thể ba có kiểu gen $Aaa$ làm MẸ lai với cây thể ba có kiểu gen $Aaa$ làm BỐ. Biết rằng chỉ các hạt phấn đơn bội ($n$) mới có khả năng nảy mầm và thụ tinh, còn noãn $n$ và $n+1$ đều thụ tinh bình thường; mọi hợp tử tạo ra đều sống sót. Tỉ lệ cây hoa trắng ở đời con $F_1$ là bao nhiêu?","opts":["$\\frac{1}{6}$ ($16.67\\%$).","$\\frac{1}{4}$ ($25.00\\%$).","$\\frac{1}{3}$ ($33.33\\%$).","$\\frac{1}{9}$ ($11.11\\%$)."],"ans":2,"exp":"Mẹ $Aaa$ tạo noãn $(\\frac{1}{6}A : \\frac{2}{6}a : \\frac{2}{6}Aa : \\frac{1}{6}aa) \\Rightarrow$ giao tử toàn lặn $(a + aa) = \\frac{2}{6} + \\frac{1}{6} = \\frac{1}{2}$. Bố $Aaa$ tạo hạt phấn đơn bội $(\\frac{1}{3}A : \\frac{2}{3}a)$. Vậy tỉ lệ cây hoa trắng ($aa + aaa$) $= \\frac{1}{2} \\times \\frac{2}{3} = \\frac{1}{3}$."},{"id":"MCQ-CL-150","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân bào & Thụ tinh Kép","q":"Ở một loài thực vật có hoa ($2n = 20$), xét 1 cặp gen $Aa$. Cây mẹ có kiểu gen $Aa$ tiến hành giảm phân và tạo thành các túi phôi đơn bội bình thường (trong mỗi túi phôi, 1 noãn và 2 nhân cực đều mang cùng 1 loại alen của noãn từ một đại bào tử nguyên phân 3 lần tạo ra!). Cây bố có kiểu gen $Aa$ giảm phân tạo hạt phấn bình thường (2 tinh tử trong mỗi hạt phấn mang cùng kiểu gen). Khi cho lai $P: Aa \\times Aa$, tỉ lệ kiểu gen của nội nhũ ($3n$) ở các hạt thu được là:","opts":["$1\\text{ }AAA : 1\\text{ }AAa : 1\\text{ }Aaa : 1\\text{ }aaa$.","$3\\text{ }AAA : 1\\text{ }aaa$.","$1\\text{ }AA : 2\\text{ }Aa : 1\\text{ }aa$.","$1\\text{ }AAA : 3\\text{ }AAa : 3\\text{ }Aaa : 1\\text{ }aaa$."],"ans":0,"exp":"Mỗi túi phôi hình thành từ 1 đại bào tử đơn bội ($A$ hoặc $a$) nguyên phân 3 lần $\\Rightarrow$ hai nhân cực hợp lại luôn có kiểu gen đồng hợp $AA$ (tỉ lệ $\\frac{1}{2}$) hoặc $aa$ (tỉ lệ $\\frac{1}{2}$). Tinh tử thứ 2 từ hạt phấn mang $A$ ($\\frac{1}{2}$) hoặc $a$ ($\\frac{1}{2}$). Tổ hợp nội nhũ $3n$: $(\\frac{1}{2}AA : \\frac{1}{2}aa) \\times (\\frac{1}{2}A : \\frac{1}{2}a) = \\frac{1}{4}AAA : \\frac{1}{4}AAa : \\frac{1}{4}Aaa : \\frac{1}{4}aaa$ (tỉ lệ $1:1:1:1$)!"}];
